
def _find_exact_time(jd_start, jd_end, lat, lon, target_val, func):
    left = jd_start
    right = jd_end
    val_left = func(left, lat, lon)
    val_right = func(right, lat, lon)
    
    if val_left > val_right and target_val <= val_left:
        val_right += 360
    if target_val < val_left and val_right > 360:
        target_val += 360
        
    for _ in range(30):
        mid = (left + right) / 2.0
        val_mid = func(mid, lat, lon)
        if val_mid < val_left and target_val >= val_left:
            val_mid += 360
            
        if val_mid < target_val:
            left = mid
        else:
            right = mid
    return left

def _get_tithi_deg(jd, lat, lon):
    p = full_panchang(jd, lat, lon)
    return (p['moon']['sid'] - p['sun']['sid']) % 360
    
def _get_nak_deg(jd, lat, lon):
    p = full_panchang(jd, lat, lon)
    return p['moon']['sid']

def _get_yog_deg(jd, lat, lon):
    p = full_panchang(jd, lat, lon)
    return (p['sun']['sid'] + p['moon']['sid']) % 360

def _get_karan_deg(jd, lat, lon):
    p = full_panchang(jd, lat, lon)
    return (p['moon']['sid'] - p['sun']['sid']) % 360

