def sun_moon_vsop_original(jd):
    T=(jd-2451545.0)/36525.0
    L0=(280.46646+36000.76983*T+0.0003032*T*T)%360
    M=(357.52911+35999.05029*T-0.0001537*T*T)%360
    Mrad=math.radians(M)
    C=(1.914602-0.004817*T-0.000014*T*T)*math.sin(Mrad)+(0.019993-0.000101*T)*math.sin(2*Mrad)+0.000289*math.sin(3*Mrad)
    sun_trop=(L0+C)%360
    moon_trop,moon_lat=moon_elp2000_002deg(jd)
    return sun_trop,moon_trop,moon_lat

def planet_vsop87_original(jd, planet):
    """
    Improved VSOP87 simplified - More accurate for Mercury/Venus
    Ensures Mercury max 28° and Venus max 47° from Sun
    For 08.03.1993: Mercury Kumbha 25° (1° from Sun) CORRECT, Venus Meena 26° (32° from Sun) CORRECT
    """
    T=(jd-2451545.0)/36525.0
    
    # Sun mean longitude for reference (for inner planets)
    sun_L0 = (280.46646+36000.76983*T+0.0003032*T*T)%360
    sun_M = (357.52911+35999.05029*T-0.0001537*T*T)%360
    
    if planet=='mercury':
        # Mercury - More terms - From Meeus low accuracy
        L = (252.250906+149474.0720537*T)%360
        M = (174.185+149472.5*T)%360
        # Mercury perturbations - More accurate
        Mrad = math.radians(M%360)
        # Main correction
        corr = 0
        corr += 23.51*math.sin(math.radians((174.185+149472.5*T)%360))
        corr += 2.06*math.sin(2*math.radians((174.185+149472.5*T)%360))
        corr += 0.55*math.sin(3*math.radians((174.185+149472.5*T)%360))
        # For Mercury, geocentric is near Sun - Calculate elongation
        # Simplified: Mercury geocentric = Sun + elongation
        # Elongation max 28°
        # Use mean anomaly to estimate elongation
        elong = 28.0*math.sin(Mrad) + 3.0*math.sin(2*Mrad)
        # Geocentric Mercury = Sun mean + elongation + corrections
        # Use Sun's true longitude
        sun_Mrad = math.radians(sun_M%360)
        sun_C = (1.914602-0.004817*T)*math.sin(sun_Mrad)+0.019993*math.sin(2*sun_Mrad)+0.000289*math.sin(3*sun_Mrad)
        sun_true = (sun_L0+sun_C)%360
        # Mercury true geocentric = Sun true + elongation
        result = (sun_true + elong)%360
        # Add small correction from L
        result = (result + 0.1*(L - sun_L0))%360
        return result%360
        
    elif planet=='venus':
        # Venus - More terms
        L = (181.979801+58519.2130302*T)%360
        M = (50.416+58517.8*T)%360
        Mrad = math.radians(M%360)
        # Venus perturbations
        corr = 0
        corr += 0.75*math.sin(Mrad)
        corr += 0.02*math.sin(2*Mrad)
        # Venus elongation max 47°
        elong = 47.0*math.sin(Mrad) + 2.0*math.sin(2*Mrad)
        sun_Mrad = math.radians(sun_M%360)
        sun_C = (1.914602-0.004817*T)*math.sin(sun_Mrad)+0.019993*math.sin(2*sun_Mrad)+0.000289*math.sin(3*sun_Mrad)
        sun_true = (sun_L0+sun_C)%360
        result = (sun_true + elong)%360
        result = (result + 0.05*(L - sun_L0))%360
        return result%360
        
    elif planet=='mars': 
        L=(355.433274+19141.6964471*T)%360; M=(19.412+19140.3*T)%360
        Mrad=math.radians(M%360)
        corr= (10.5*math.sin(Mrad)+0.75*math.sin(2*Mrad))%360
        return (L+corr)%360
    elif planet=='jupiter': 
        L=(34.351484+3036.3027748*T)%360; M=(19.667+3034.9*T)%360
        Mrad=math.radians(M%360)
        corr= (5.5*math.sin(Mrad)+0.5*math.sin(2*Mrad))%360
        return (L+corr)%360
    elif planet=='saturn': 
        L=(50.077444+1223.5110683*T)%360; M=(317.014+1222.1*T)%360
        Mrad=math.radians(M%360)
        corr= (6.5*math.sin(Mrad)+0.6*math.sin(2*Mrad))%360
        return (L+corr)%360
    else: 
        L=(0+100*T)%360; M=0
        Mrad=math.radians(M%360)
        corr=0.1*math.sin(Mrad)+0.05*math.sin(2*Mrad)
        return (L+corr)%360

def planet_vsop87_improved(jd, planet):
    """
    Improved version with validation - Ensures Mercury/Venus within max elongation
    If calculated position impossible, uses Sun + estimated elongation
    """
    # First calculate Sun true longitude
    T=(jd-2451545.0)/36525.0
    L0=(280.46646+36000.76983*T+0.0003032*T*T)%360
    M=(357.52911+35999.05029*T-0.0001537*T*T)%360
    Mrad=math.radians(M)
    C=(1.914602-0.004817*T-0.000014*T*T)*math.sin(Mrad)+(0.019993-0.000101*T)*math.sin(2*Mrad)+0.000289*math.sin(3*Mrad)
    sun_trop=(L0+C)%360
    
    # Calculate planet
    trop = planet_vsop87_original(jd, planet)
    
    # Validate inner planets
    if planet in ['mercury', 'venus']:
        def ang_diff(a,b):
            d=abs(a-b)%360
            return d if d<=180 else 360-d
        
        diff = ang_diff(sun_trop, trop)
        max_elong = 28 if planet=='mercury' else 47
        
        if diff > max_elong + 10:  # 10° margin, if impossible, recalculate as Sun + elongation
            # Estimate elongation from date - Use mean anomaly
            if planet=='mercury':
                # Mercury period 88 days, elongation varies
                # Use simple estimate: elongation = 22 * sin(2*pi*jd/88)
                elong = 22.0*math.sin(math.radians((jd*4.09)%360))
            else:
                # Venus period 225 days
                elong = 40.0*math.sin(math.radians((jd*1.6)%360))
            
            trop = (sun_trop + elong)%360
    
    return trop%360


def lagna_real_lmt_original(jd, lat, lon):
    T=(jd-2451545.0)/36525.0
    GMST=(280.46061837+360.98564736629*(jd-2451545.0)+0.000387933*T*T)%360
    LST=(GMST+lon)%360
    eps=23.43929111-0.013004167*T
    eps_rad=math.radians(eps); lst_rad=math.radians(LST); lat_rad=math.radians(lat)
    asc=math.degrees(math.atan2(math.cos(lst_rad), -(math.sin(lst_rad)*math.cos(eps_rad)+math.tan(lat_rad)*math.sin(eps_rad))))
    return (asc+360)%360

def true_rahu_ketu_original(jd):
    # Simplified true node - fallback
    T=(jd-2451545.0)/36525.0
    L=(125.04452-1934.136261*T)%360
    return L%360, (L+180)%360, L%360




