def download_nasa_ephemeris_all(ephe_dir="/mnt/data/ephe", which="minimal", progress_callback=None):
    import urllib.request, ssl, os
    os.makedirs(ephe_dir, exist_ok=True)
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    if which == "minimal":
        files_to_download = {
            'de440s.bsp': NASA_EPHEMERIS_FILES['de440s.bsp'],
            'sepl_19.se1': SWISS_EPHEMERIS_FILES['sepl_19.se1'],
            'sepl_20.se1': SWISS_EPHEMERIS_FILES['sepl_20.se1'],
            'semo_19.se1': SWISS_EPHEMERIS_FILES['semo_19.se1'],
            'semo_20.se1': SWISS_EPHEMERIS_FILES['semo_20.se1'],
        }
    elif which == "de441":
        files_to_download = {'de441.bsp': NASA_EPHEMERIS_FILES['de441.bsp']}
    elif which == "de440":
        files_to_download = {'de440.bsp': NASA_EPHEMERIS_FILES['de440.bsp']}
    elif which == "swiss":
        files_to_download = SWISS_EPHEMERIS_FILES
    else:
        files_to_download = {**NASA_EPHEMERIS_FILES, **SWISS_EPHEMERIS_FILES}
    downloaded = {}
    failed = {}
    for filename, info in files_to_download.items():
        filepath = os.path.join(ephe_dir, filename)
        if os.path.exists(filepath):
            downloaded[filename] = {'path': filepath, 'info': info, 'status': 'exists'}
            continue
        try:
            url = info['url']
            print(f"Downloading {filename} ({info['size']})...")
            req = urllib.request.Request(url, headers={'User-Agent': 'UltimatePanchang/1.0'})
            urllib.request.urlretrieve(url, filepath)
            downloaded[filename] = {'path': filepath, 'info': info, 'status': 'downloaded'}
            print(f"Downloaded {filename}")
        except Exception as e:
            failed[filename] = {'info': info, 'error': str(e)}
            print(f"Failed {filename}: {e}")
    return {'downloaded': downloaded, 'failed': failed, 'dir': ephe_dir}

def list_nasa_ephemeris_available(ephe_dir="/mnt/data/ephe"):
    import os
    available = {}
    missing = {}
    all_files = {**NASA_EPHEMERIS_FILES, **SWISS_EPHEMERIS_FILES}
    for filename, info in all_files.items():
        filepath = os.path.join(ephe_dir, filename)
        if os.path.exists(filepath):
            size_mb = os.path.getsize(filepath) / (1024*1024)
            available[filename] = {'path': filepath, 'size_mb': size_mb, 'info': info}
        else:
            missing[filename] = info
    return available, missing

def get_best_de_ephemeris(ephe_dir="/mnt/data/ephe"):
    import os
    available, missing = list_nasa_ephemeris_available(ephe_dir)
    preference = ['de441.bsp', 'de440.bsp', 'de431.bsp', 'de440s.bsp']
    for pref in preference:
        if pref in available:
            return available[pref]['path'], available[pref]['info'], pref
    return None, None, None

