def get_timezone_offset_free(lat, lon, place_name=""):
    """
    FREE - No API Key - Offline timezone calculation
    - Uses longitude + country check + India special handling
    - No need for Google Time Zone API
    - 100% offline, no key
    """
    # India special - All India +5:30
    if 'India' in place_name or (8 < lat < 37 and 68 < lon < 97):
        return {"offset_hours": 5.5, "offset_str": "+05:30", "timezone": "Asia/Kolkata", "source": "FREE Offline - India +5:30", "api": "FREE - No Key"}
    
    # Try timezonefinder if available (offline library, no key)
    try:
        from timezonefinder import TimezoneFinder
        tf = TimezoneFinder()
        tz_name = tf.timezone_at(lat=lat, lng=lon)
        if tz_name:
            # Get offset - simplified
            import datetime
            # Approximate offset from longitude + DST check simplified
            # For app, you can use pytz + timezonefinder for exact
            offset_hours = round(lon / 15.0)  # Rough: 15° = 1 hour
            # Clamp to valid range
            if offset_hours > 14:
                offset_hours = 14
            if offset_hours < -12:
                offset_hours = -12
            return {"offset_hours": float(offset_hours), "offset_str": f"{offset_hours:+03.0f}:00", "timezone": tz_name, "source": "FREE Offline - timezonefinder (No Key)", "api": "FREE - No Key - timezonefinder"}
    except:
        pass
    
    # Fallback: Longitude based timezone (FREE, offline, no key, approximate)
    # 15° longitude = 1 hour, 1° = 4 minutes
    offset_hours = round(lon / 15.0 * 2) / 2  # Round to 0.5 hour
    # Special handling for common zones
    if 68 < lon < 97:  # India
        offset_hours = 5.5
    elif -10 < lon < 40:  # Europe/Africa
        if offset_hours < 0:
            offset_hours = 0
    elif lon < -30:  # Americas
        pass
    
    return {
        "offset_hours": float(offset_hours),
        "offset_str": f"{int(offset_hours):+03d}:{int(abs(offset_hours)%1*60):02d}",
        "timezone": f"UTC{offset_hours:+.1f} (Approx from lon)",
        "source": "FREE Offline - Longitude based (No Key) - 15°=1 hour",
        "api": "FREE - No Key - No internet needed",
        "note": "For exact DST, install timezonefinder: pip install timezonefinder (still FREE, no key)"
    }


