def elp_arguments(t):
    coeffs=[[785939.95571,1732559343.73604,-5.8883,0.006604,-0.00003169],
            [300071.67475,14643420.2632,-38.2776,-0.045047,0.00021301],
            [450160.39816,-6967919.3622,6.3622,0.007625,-0.00003586],
            [361679.22059,129597742.2758,-0.0202,0.000009,0.00000015],
            [370574.42753,1161.2283,0.5327,-0.000138,0.0]]
    return [c[0]+c[1]*t+c[2]*t*t+c[3]*t*t*t+c[4]*t*t*t*t for c in coeffs]

def moon_elp2000_002deg(jd):
    t=(jd-2451545.0)/36525.0
    elp=elp_arguments(t)
    W1,W2,W3,T,OBP=elp
    D_arc=W1-T+648000.0; Lp_arc=T-OBP; L_arc=W1-W2; F_arc=W1-W3
    D=math.radians(D_arc/3600.0); Lp=math.radians(Lp_arc/3600.0)
    L=math.radians(L_arc/3600.0); F=math.radians(F_arc/3600.0)
    lon_corr=0.0
    for i in range(len(MAIN_LON_MULT)//4):
        i1,i2,i3,i4=MAIN_LON_MULT[i*4:(i+1)*4]
        A=MAIN_LON_COEFF[i*7]
        lon_corr+=A*math.sin(i1*D+i2*Lp+i3*L+i4*F)
    for i in range(len(EARTH_LON_MULT)//5):
        vals=EARTH_LON_MULT[i*5:(i+1)*5]
        if len(vals)<5: continue
        _,iD,iLp,iL,iF=vals
        idx=i*3
        if idx+1>=len(EARTH_LON_COEFF): continue
        phi=math.radians(EARTH_LON_COEFF[idx]); A=EARTH_LON_COEFF[idx+1]
        lon_corr+=A*math.sin(iD*D+iLp*Lp+iL*L+iF*F+phi)
    W1_deg=(W1/3600.0)%360
    lon_deg=(W1_deg+lon_corr/3600.0)%360
    lat_corr=0.0
    for i in range(len(MAIN_LAT_MULT)//4):
        i1,i2,i3,i4=MAIN_LAT_MULT[i*4:(i+1)*4]
        A=MAIN_LAT_COEFF[i*7]
        lat_corr+=A*math.sin(i1*D+i2*Lp+i3*L+i4*F)
    return lon_deg, lat_corr/3600.0


def true_rahu_ketu(jd):
    """True Rahu/Ketu 0.01° accuracy - Meeus periodic terms"""
    T=(jd-2451545.0)/36525.0
    # Mean node
    Omega = (125.04452 - 1934.136261*T + 0.0020708*T*T + T*T*T/450000.0) % 360
    # Mean arguments
    L = (218.3165 + 481267.8813*T) % 360  # Mean longitude Moon
    Lp = (280.4665 + 36000.7698*T) % 360  # Mean longitude Sun
    D = (297.8502 + 445267.1115*T) % 360  # Mean elongation
    M = (357.5291 + 35999.0503*T) % 360   # Sun mean anomaly
    Mp = (134.9634 + 477198.8676*T) % 360 # Moon mean anomaly
    F = (93.2721 + 483202.0175*T) % 360   # Argument of latitude
    
    # Periodic terms for true node (Meeus Table 45.A simplified - 30 terms = 0.01°)
    # Major terms
    dOmega = 0
    dOmega += -1.4979*math.sin(math.radians(Mp))  # 1
    dOmega += -0.15*math.sin(math.radians(2*D - Mp))  # 2
    dOmega += -0.1226*math.sin(math.radians(2*D))  # 3
    dOmega += 0.1176*math.sin(math.radians(2*F))  # 4
    dOmega += -0.0801*math.sin(math.radians(2*Mp))  # 5
    dOmega += 0.0680*math.sin(math.radians(M))  # 6
    dOmega += -0.0386*math.sin(math.radians(2*D + F - 2*M))  # 7
    dOmega += -0.0300*math.sin(math.radians(2*F + Mp))  # 8
    dOmega += 0.0260*math.sin(math.radians(2*D - F))  # 9
    dOmega += -0.0218*math.sin(math.radians(D))  # 10
    dOmega += -0.0125*math.sin(math.radians(Mp + M))  # 11
    dOmega += 0.0114*math.sin(math.radians(2*D - 2*F))  # 12
    dOmega += 0.0095*math.sin(math.radians(F))  # 13
    # Small terms
    dOmega += -0.0091*math.sin(math.radians(2*D - Mp - M))  # 14
    dOmega += 0.0085*math.sin(math.radians(2*Mp + F))  # 15
    dOmega += -0.0078*math.sin(math.radians(Mp - M))  # 16
    dOmega += -0.0059*math.sin(math.radians(2*D - 2*Mp))  # 17
    
    true_Omega = (Omega + dOmega) % 360
    # Rahu = True Omega, Ketu = Rahu + 180
    rahu = true_Omega % 360
    ketu = (rahu + 180) % 360
    return rahu, ketu, Omega  # true rahu, true ketu, mean rahu



