def search_place_worldwide(query):
    """Search ANY place in world - Country/City/Village/Place - No error"""
    if not query or not isinstance(query,str): query="Pune, India"
    query=query.strip()
    if not query: query="Pune, India"
    # 1. OFFLINE exact match
    if query in WORLD_PLACES:
        lat,lon=WORLD_PLACES[query]
        return {'lat':lat,'lon':lon,'name':query,'source':'offline-exact','found':True}
    # 2. OFFLINE partial match
    qlow=query.lower()
    for name,(lat,lon) in WORLD_PLACES.items():
        if qlow in name.lower() or name.lower() in qlow:
            return {'lat':lat,'lon':lon,'name':name,'source':'offline-partial','found':True}
    # 3. ONLINE search for any village (needs internet once, then cached)
    try:
        import urllib.request, urllib.parse
        url=f"https://nominatim.openstreetmap.org/search?q={urllib.parse.quote(query)}&format=json&limit=1"
        req=urllib.request.Request(url, headers={'User-Agent':'PanchangApp/1.0'})
        with urllib.request.urlopen(req, timeout=5) as resp:
            data=json.loads(resp.read().decode())
            if data:
                lat=float(data[0]['lat']); lon=float(data[0]['lon']); display=data[0]['display_name']
                WORLD_PLACES[query]=(lat,lon)
                return {'lat':lat,'lon':lon,'name':display,'source':'online','found':True}
    except: pass
    # 4. No error - return Pune default
    return {'lat':18.5204,'lon':73.8567,'name':'Pune, India (default - place not found, using Pune)','source':'default','found':False,'error':f'Place "{query}" not in offline 500 cities. For villages, need internet for first search.'}

def live_panchang_now(lat=18.5204, lon=73.8567):
    """Live Panchang for NOW with Yoga, Karana, Pada, Navamsa, Retrograde"""
    try:
        import datetime
        now=datetime.datetime.now()
        jd=to_jd(now.year, now.month, now.day, now.hour, now.minute, now.second, lat=lat, lon=lon)
        pan=full_panchang(jd, lat, lon)
        if pan.get('error'): return pan
        yogas=["Vishkambha","Priti","Ayushman","Saubhagya","Shobhana","Atiganda","Sukarma","Dhriti","Shula","Ganda","Vriddhi","Dhruva","Vyaghata","Harshana","Vajra","Siddhi","Vyatipata","Variyana","Parigha","Shiva","Siddha","Sadhya","Shubha","Shukla","Brahma","Indra","Vaidhriti"]
        yoga_val=(pan['sun']['sid']+pan['moon']['sid'])%360
        yoga_num=int(yoga_val/13.333333)%27
        yoga_name=yogas[yoga_num]
        karanas=["Bava","Balava","Kaulava","Taitila","Garaja","Vanija","Vishti"]
        karana_num=int((pan['tithi_deg']%360)/6)%7
        karana_name=karanas[karana_num]
        pada=int((pan['moon']['sid']%13.333333)/3.333333)+1
        navamsa=int((pan['moon']['sid']%30)/3.333333)
        jd_yest=jd-1; pan_yest=full_panchang(jd_yest, lat, lon)
        retro={}
        if not pan_yest.get('error'):
            for p in pan['planets']:
                diff=(pan['planets'][p]['trop']-pan_yest['planets'][p]['trop'])%360
                if diff>180: diff-=360
                retro[p]=diff<0
        return {'time_ist':now.strftime("%d-%m-%Y %H:%M:%S IST"),'jd':jd,'ayanamsa':pan['ayanamsa'],'tithi':pan['tithi'],'tithi_deg':pan['tithi_deg'],'nakshatra':pan['moon']['nakshatra'],'nak_pada':pada,'navamsa':navamsa,'yoga':yoga_name,'yoga_deg':yoga_val,'karana':karana_name,'moon_sid':pan['moon']['sid'],'sun_sid':pan['sun']['sid'],'lagna_sid':pan['lagna']['sid'],'rahu':pan['rahu'],'rahu_true':pan['rahu'],'ketu_true':pan['ketu'],'rahu_mean':pan.get('rahu_mean',pan['rahu']),'retro':retro,'planets':pan['planets'],'error':None}
    except Exception as e:
        return {'error':str(e),'time_ist':'error'}

def panchang_for_place(place_query, year=None, month=None, day=None, hour=7, minute=0):
    """Get Panchang for ANY place in world by name - No error"""
    try:
        place=search_place_worldwide(place_query)
        lat,lon=place['lat'],place['lon']
        if year is None:
            import datetime; now=datetime.datetime.now()
            year,month,day=now.year,now.month,now.day
            hour,minute=now.hour,now.minute
        if 'India' in place['name']: jd=to_jd(year, month, day, hour, minute, 0, lat=lat, lon=lon)
        else: jd=to_jd(year,month,day,hour,minute,0)
        pan=full_panchang(jd,lat,lon)
        live=live_panchang_now(lat,lon)
        return {'place_input':place_query,'place_found':place,'panchang':pan,'live':live,'error':None}
    except Exception as e:
        return {'error':str(e),'place_input':place_query}

