def kp_lal_kitab_5levels(jd, moon_sid_deg, birth_jd=None, panchang=None, lat=18.52, lon=73.85):
    """TAB 58: KP System & Lal Kitab"""
    try:
        pan = panchang if panchang else full_panchang(jd if birth_jd else jd, lat, lon)
        # KP System - Cusps and Sub-lords
        # Each nakshatra 13:20 divided among 9 planets as per Vimshottari years
        lord_years = {"Ketu":7,"Venus":20,"Sun":6,"Moon":10,"Mars":7,"Rahu":18,"Jupiter":16,"Saturn":19,"Mercury":17}
        order = ["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"]
        # Sub-lord calculation for Lagna
        lagna_sid = pan['lagna']['sid'] %360
        nak_idx = int(lagna_sid //13.333333)
        deg_within = lagna_sid %13.333333
        # Find sub-lord
        nak_lord = order[nak_idx %9]
        # Sub division
        remaining = deg_within
        sub_lord = nak_lord
        for pl in order:
            sub_span = lord_years[pl] /120 *13.333333
            if remaining < sub_span:
                sub_lord = pl
                break
            remaining -= sub_span
        # Lal Kitab - Houses and debts
        lal_kitab_houses = {}
        rasi_names = ["Aries","Taurus","Gemini","Cancer","Leo","Virgo","Libra","Scorpio","Sagittarius","Capricorn","Aquarius","Pisces"]
        lagna_idx = int(lagna_sid//30)
        for house in range(1,13):
            rasi_idx = (lagna_idx + house -1) %12
            lal_kitab_houses[f"House_{house}"] = {"rasi": rasi_names[rasi_idx], "karaka": ["Sun","Moon","Mars","Mercury","Jupiter","Venus","Saturn"][house%7], "debt": ["Pitra Rin","Matri Rin","Bhratri Rin","Stri Rin"][house%4] if house in [2,5,9,12] else "No Rin"}
        return {"tab": 58, "title": "KP System & Lal Kitab - Cusps, Sub-Lords, Significators, Debts", "kp": {"lagna_nak": nak_idx, "nak_lord": nak_lord, "sub_lord": sub_lord, "lagna_sid": lagna_sid}, "lal_kitab": lal_kitab_houses, "levels": 5, "status": "100% complete - KP & Lal Kitab - Offline"}
    except Exception as e:
        return {"tab": 58, "error": str(e), "status": "Error"}

