        # Jupiter cycle: Jupiter takes ~11.86 years for 1 revolution, but Barhaspatya Samvatsara uses ~1 year per rasi
        # Jupiter's position gives Guru Samvatsara
        jup_sid = pan['planets'].get('jupiter',{}).get('sid', 0) %360
        jup_rasi_idx = int(jup_sid //30)
        # Barhaspatya Samvatsara - 60 year cycle based on Jupiter's mean motion
        # Jupiter moves 30° per year approx for Samvatsara (actually 360/11.86 = 30.35° per year, but for Samvatsara calendar, 1 rasi = 1 year)
        # Barhaspatya name = same as Prabhavadi but based on Jupiter
        barhaspatya_idx = jup_rasi_idx  # Simplified: Jupiter rasi determines year
        # Actually 60-year cycle: (Jupiter's sidereal years since epoch) %60
        # Years since 3102 BCE Kali Yuga
        kali_jd = 588465.5
        years_since_kali = (jd_use - kali_jd) / 365.2425
        # Jupiter cycle 11.86 years, so jupiter_cycles = years_since_kali / 11.86
        # For 60-year cycle, use (years_since_kali) %60 is Chandra Samvatsara
        
