        # ====================================================================
        # BALA CALCULATIONS - Chandra, Ravi, Guru, Tara
        # ====================================================================
        # Chandra Bala: Moon in 1,3,6,7,10,11 from Janma Rashi = Shubha
        # For generic, assume Janma Rashi = Moon Rashi (birth moon = current moon for demo)
        # Actually for calculator, user gives birth moon rashi
        janma_rasi_idx = moon_rasi_idx  # For this instant calc, birth = current; for calculator function, will be different
        chandra_bala_good_houses = [1,3,6,7,10,11]
        chandra_bala_bad_houses = [2,4,5,8,9,12]
        
        # For any current moon rasi vs janma rasi:
        def chandra_bala_check(current_moon_rasi_idx, janma_rasi_idx):
            house = (current_moon_rasi_idx - janma_rasi_idx) %12 +1
            if house in [1,3,6,7,10,11]:
                return {"bala":"Good","house":house,"result":"Shubha - Chandra Bala good"}
            else:
                return {"bala":"Bad","house":house,"result":"Ashubha - Chandra Bala bad, avoid"}
        
        # Ravi Bala (Sun strength): Sun in 3,6,10,11 from Janma = Good? Actually Ravi Bala 3,6,10,11 from Janma Rashi is Shubha
        def ravi_bala_check(current_sun_rasi_idx, janma_rasi_idx):
            house = (current_sun_rasi_idx - janma_rasi_idx) %12 +1
            if house in [3,6,10,11]:
                return {"bala":"Good","house":house,"result":"Shubha - Ravi Bala good"}
            else:
                return {"bala":"Bad","house":house,"result":"Ashubha - Ravi Bala bad"}
        
        # Guru Bala: Jupiter in 2,5,7,9,11 from Janma Rashi = Good
        def guru_bala_check(current_jup_rasi_idx, janma_rasi_idx):
            house = (current_jup_rasi_idx - janma_rasi_idx) %12 +1
            if house in [2,5,7,9,11]:
                return {"bala":"Good","house":house,"result":"Shubha - Guru Bala good"}
            else:
                return {"bala":"Bad","house":house,"result":"Ashubha - Guru Bala bad - No Vivah, Grihapravesh"}
        
        # Tara Bala: (Dina Nak - Janma Nak) %9 -> 2,4,6,8,9 Shubha
        def tara_bala_check(current_nak_idx, janma_nak_idx):
            tara = (current_nak_idx - janma_nak_idx) %9 +1
            if tara in [2,4,6,8,9]:
                return {"bala":"Good","tara":tara,"name":["Janma","Sampat","Vipat","Kshema","Pratyari","Sadhaka","Vadha","Mitra","Atimitra"][tara-1],"result":f"Shubha - Tara {tara}"}
            else:
                return {"bala":"Bad","tara":tara,"name":["Janma","Sampat","Vipat","Kshema","Pratyari","Sadhaka","Vadha","Mitra","Atimitra"][tara-1],"result":f"Ashubha - Tara {tara}"}
        
        # Current Bala for this JD
        chandra_bala_current = chandra_bala_check(moon_rasi_idx, janma_rasi_idx)
        ravi_bala_current = ravi_bala_check(sun_rasi_idx, janma_rasi_idx)
        guru_rasi_idx = int(jup_sid //30)
        guru_bala_current = guru_bala_check(guru_rasi_idx, janma_rasi_idx)
        tara_bala_current = tara_bala_check(nak_idx, nak_idx)
        
        # ====================================================================
        # 100 YEAR CALCULATOR FUNCTION - Worldwide
        # ====================================================================
        def calculate_muhurta_for_next_days(event_type, start_jd, days_ahead, user_janma_rasi_idx, user_janma_nak_idx, event_lat, event_lon, required_balas):
            """
            Calculator: Finds auspicious muhurta in next days_ahead days
            event_type: e.g., "Vivah", "Grihapravesh", "Bhoomi Pujan", etc
            required_balas: list of ["Chandra","Ravi","Guru","Tara"] - user can select one/some/all
            """
            results = []
            # Find muhurta definition
            muhurta_def = None
            for md in muhurta_definitions:
                if event_type.lower() in md["name"].lower() or md["name"].lower() in event_type.lower():
                    muhurta_def = md
                    break
            if not muhurta_def:
                muhurta_def = muhurta_definitions[15]  # Default Grihapravesh
            
            for offset in range(days_ahead):
                jd_check = start_jd + offset
                try:
                    pan_check = full_panchang(jd_check, event_lat, event_lon)
                    moon_sid_check = pan_check['moon']['sid'] %360
                    sun_sid_check = pan_check['sun']['sid'] %360
                    jup_sid_check = pan_check['planets'].get('jupiter',{}).get('sid',0) %360
                    moon_rasi_check = int(moon_sid_check //30)
                    sun_rasi_check = int(sun_sid_check //30)
                    jup_rasi_check = int(jup_sid_check //30)
                    nak_check = int(moon_sid_check //13.333333) %27
                    tithi_deg_check = (pan_check['moon'].get('trop', moon_sid_check+24) - pan_check['sun'].get('trop', sun_sid_check+24)) %360
                    tithi_num_check = int(tithi_deg_check //12) +1
                    vara_num_check = int((jd_check + 1.5) %7)
                    
                    # Check muhurta conditions (simplified: tithi, vara, nakshatra)
                    # For demo, check if nakshatra in allowed list and tithi shubha and vara shubha
                    # Real implementation would parse muhurta_def's tithi/vara/nak lists
                    
                    # Bala checks
                    bala_results = {}
                    all_bala_good = True
                    
                    if "Chandra" in required_balas:
                        cb = chandra_bala_check(moon_rasi_check, user_janma_rasi_idx)
                        bala_results["Chandra"] = cb
                        if cb["bala"]=="Bad":
                            all_bala_good = False
                    if "Ravi" in required_balas:
                        rb = ravi_bala_check(sun_rasi_check, user_janma_rasi_idx)
                        bala_results["Ravi"] = rb
                        if rb["bala"]=="Bad":
                            all_bala_good = False
                    if "Guru" in required_balas:
                        gb = guru_bala_check(jup_rasi_check, user_janma_rasi_idx)
                        bala_results["Guru"] = gb
                        if gb["bala"]=="Bad":
                            all_bala_good = False
                    if "Tara" in required_balas or "Nakshatra" in required_balas:
                        tb = tara_bala_check(nak_check, user_janma_nak_idx)
                        bala_results["Tara"] = tb
                        if tb["bala"]=="Bad":
                            all_bala_good = False
                    
                    # If all required balas good and basic muhurta conditions met, add as auspicious
                    # For simplicity, consider all days where balas good as potential muhurta
                    if all_bala_good:
                        # Also check tithi: avoid Rikta 4,9,14 and Amavasya for most
                        tithi_shubha = tithi_num_check not in [4,9,14,15,30] or muhurta_def["name"]=="Rogotpatti"  # Rikta avoid
                        if tithi_shubha:
                            results.append({
                                "jd": jd_check,
                                "date": f"Day +{offset}",
                                "tithi": tithi_num_check,
                                "vara": vara_names_short[vara_num_check],
                                "nakshatra": nak_names[nak_check],
                                "moon_rasi": rasi_names[moon_rasi_check],
                                "sun_rasi": rasi_names[sun_rasi_check],
                                "bala": bala_results,
                                "muhurta": muhurta_def["name"],
                                "beneficial": "Yes - All selected Balas good" if all_bala_good else "No",
                                "score": len([b for b in bala_results.values() if b["bala"]=="Good"])
                            })
                except Exception as e:
                    continue
                if len(results)>=20:  # Limit to 20 best for demo
                    break
            return results
        
        # Example calculation for next 30 days for Grihapravesh with all balas
        # Use birth jd as user birth for demo
        example_muhurtas = calculate_muhurta_for_next_days("Grihapravesh", jd_use, 60, janma_rasi_idx, nak_idx, lat, lon, ["Chandra","Ravi","Guru","Tara"])
        
        # ====================================================================
