        # Dwipushkar Yoga: Bhadra Tithi (2,7,12) + Dwipushkar Nakshatra + Vara - Doubles result
        dwipushkar_tithis = [2,7,12,17,22,27]  # Dwitiya, Saptami, Dwadashi both paksha
