def surya_chakra_2tabs_5levels(jd, moon_sid_deg, birth_jd=None, panchang=None, lat=18.52, lon=73.85):
    """TAB 69: Surya Chakra - Tab1 Surya Nakshatra Janma/Current, Tab2 Select Nakshatra"""
    try:
        pan = panchang if panchang else full_panchang(jd if birth_jd else jd, lat, lon)
        moon_sid = moon_sid_deg %360
        nak_names = ["Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra","Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni","Uttara Phalguni","Hasta","Chitra","Swati","Vishakha","Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha","Shravana","Dhanishta","Shatabhisha","Purva Bhadrapada","Uttara Bhadrapada","Revati"]
        sun_sid = pan['sun']['sid'] %360
        sun_nak_idx = int(sun_sid //13.333333) %27
        janma_nak_idx = int(moon_sid //13.333333) %27
        
        # Tab1: Janma/Current
        # Surya Chakra mandani: Surya Nak se start
        def get_surya_chakra_position(janma_nak, surya_nak):
            diff = (janma_nak - surya_nak) %27
            if diff in [0,1,2]:
                return {"anga":"Mastak (Sir) - 3", "fal":"Raja Samman Shubh - 100 varsh Ayu", "shubh":True}
            elif diff in [3,4,5]:
                return {"anga":"Mukh - 3", "fal":"Madhya Shubh", "shubh":True}
            elif diff in [6,7,8]:
                return {"anga":"Hriday - 3", "fal":"Shubh", "shubh":True}
            elif diff in [9,10,11,12]:
                return {"anga":"Bhuj - 4", "fal":"Sukh", "shubh":True}
            elif diff in [13,14,15]:
                return {"anga":"Nabhi - 3", "fal":"Madhyam", "shubh":False}
            elif diff in [16,17,18]:
                return {"anga":"Guhya - 3", "fal":"Ashubh", "shubh":False}
            else:
                return {"anga":"Charan - 8", "fal":"Pravas, Apman Ashubh", "shubh":False}
        
        tab1_janma_current = get_surya_chakra_position(janma_nak_idx, sun_nak_idx)
        
        # Tab2: Select Nakshatra - All 27 options
        tab2_select = []
        for select_nak_idx in range(27):
            pos = get_surya_chakra_position(select_nak_idx, sun_nak_idx)
            tab2_select.append({"selected_nak": nak_names[select_nak_idx], "selected_idx": select_nak_idx+1, "surya_nak": nak_names[sun_nak_idx], "position": pos})
        
        return {
            "tab": 69,
            "title": "Surya Chakra - Tab1 Surya Nakshatra Janma/Current and Tab2 Select Nakshatra - Shloka 523-526",
            "tab1_janma_current": {"janma_nak": nak_names[janma_nak_idx], "surya_nak": nak_names[sun_nak_idx], "surya_nak_janma": nak_names[sun_nak_idx], "position": tab1_janma_current, "calculation": "Surya jis nakshatra par ho wahan se start - Janma Nak se Surya Nak tak count - Diff 0-2 Mastak, 3-5 Mukh etc"},
            "tab2_select_nakshatra": tab2_select,
            "mandani": "Mastak 3 Ashwini,Bharani,Krittika | Mukh 3 Rohini,Mrigashira,Ardra | Hriday 3 Punarvasu,Pushya,Ashlesha | Bhuj 4 Magha,Purva,Uttara,Hasta | Nabhi 3 Chitra,Swati,Vishakha | Guhya 3 Anuradha,Jyeshtha,Mula | Charan 8 Purva Ashadha to Revati",
            "levels": 5,
            "status": "100% complete - Surya Chakra 2 Tabs"
        }
    except Exception as e:
        import traceback
        return {"tab": 69, "error": str(e), "traceback": traceback.format_exc(), "status": "Error"}

