def calculate_benefic_malefic_ratings(jd, panchang, lat, lon):
    """Page 7: Planets Benefic-Malefic Ratings table"""
    try:
        pan = panchang
        lagna_sid = pan['lagna']['sid']
        lagna_rashi = int(lagna_sid // 30) + 1
        planets_sid = {}
        planets_sid['Sun'] = pan['sun']['sid']
        planets_sid['Moon'] = pan['moon']['sid']
        planets_sid['Mercury'] = pan['planets'].get('mercury', {}).get('sid', 0)
        planets_sid['Venus'] = pan['planets'].get('venus', {}).get('sid', 0)
        planets_sid['Mars'] = pan['planets'].get('mars', {}).get('sid', 0)
        planets_sid['Jupiter'] = pan['planets'].get('jupiter', {}).get('sid', 0)
        planets_sid['Saturn'] = pan['planets'].get('saturn', {}).get('sid', 0)
        planets_sid['Rahu'] = pan['rahu']
        planets_sid['Ketu'] = pan['ketu']
        natural_benefic = {'Jupiter': 10, 'Venus': 9, 'Moon': 7, 'Mercury': 6, 'Sun': 3, 'Mars': 2, 'Saturn': 1, 'Rahu': 0, 'Ketu': 0}
        tithi_deg = pan.get('tithi_deg', 0)
        if tithi_deg < 180:
            natural_benefic['Moon'] = 9
        else:
            natural_benefic['Moon'] = 4
        functional_ratings = {}
        rashi_lords = {1:"Mars",2:"Venus",3:"Mercury",4:"Moon",5:"Sun",6:"Mercury",7:"Venus",8:"Mars",9:"Jupiter",10:"Saturn",11:"Saturn",12:"Jupiter"}
        for planet_name in planets_sid.keys():
            if planet_name in ['Rahu','Ketu']:
                functional_ratings[planet_name] = 5
                continue
            ruled_houses = []
            for house in range(1,13):
                rashi = (lagna_rashi + house - 1 - 1) % 12 + 1
                if rashi_lords[rashi] == planet_name:
                    ruled_houses.append(house)
            rating = 5
            for house in ruled_houses:
                if house in [1,5,9]:
                    rating += 3
                elif house in [4,7,10]:
                    rating += 1
                elif house in [6,8,12]:
                    rating -= 3
                elif house in [2]:
                    rating -= 1
            rating = max(0, min(10, rating))
            functional_ratings[planet_name] = rating
        combined = {}
        for p in planets_sid.keys():
            nat = natural_benefic.get(p, 5)
            func = functional_ratings.get(p, 5)
            combined[p] = (nat * 0.4 + func * 0.6)
        table = []
        rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"]
        for p_name, sid in planets_sid.items():
            if sid == 0 and p_name in ['Mercury','Venus','Mars','Jupiter','Saturn']:
                continue
            rashi_num = int(sid // 30) + 1
            rashi_name = rashi_names[rashi_num-1]
            d, m, s = deg_to_dms(sid % 30)
            table.append({'planet': p_name, 'sid_deg': sid, 'rashi': rashi_name, 'rashi_num': rashi_num, 'ansh': d, 'kala': m, 'vikala': int(s), 'natural_benefic': natural_benefic.get(p_name, 5), 'functional_benefic': functional_ratings.get(p_name, 5), 'combined_rating': round(combined.get(p_name, 5), 2), 'nature': 'Benefic' if combined.get(p_name,5) >=6 else 'Malefic' if combined.get(p_name,5) <=4 else 'Neutral', 'natural_nature': 'Natural Benefic' if natural_benefic.get(p_name,5) >=6 else 'Natural Malefic' if natural_benefic.get(p_name,5) <=3 else 'Natural Neutral'})
        return {'title': 'Planets Benefic-Malefic Ratings', 'lagna_rashi': rashi_names[lagna_rashi-1], 'lagna_rashi_num': lagna_rashi, 'table': table, 'natural_benefic_planets': ['Jupiter','Venus','Moon (Shukla)','Mercury (with benefic)'], 'natural_malefic_planets': ['Saturn','Mars','Sun','Rahu','Ketu'], 'calculation': 'Natural 40% + Functional 60% based on lordship. Trikona lords benefic, Dusthana malefic'}
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_aspects_on_planets(jd, panchang, lat, lon):
    """Page 7: Aspects on Planets table"""
    try:
        pan = panchang
        planets_sid = {}
        planets_sid['Sun'] = pan['sun']['sid']
        planets_sid['Moon'] = pan['moon']['sid']
        planets_sid['Mercury'] = pan['planets'].get('mercury', {}).get('sid', 0)
        planets_sid['Venus'] = pan['planets'].get('venus', {}).get('sid', 0)
        planets_sid['Mars'] = pan['planets'].get('mars', {}).get('sid', 0)
        planets_sid['Jupiter'] = pan['planets'].get('jupiter', {}).get('sid', 0)
        planets_sid['Saturn'] = pan['planets'].get('saturn', {}).get('sid', 0)
        planets_sid['Rahu'] = pan['rahu']
        planets_sid['Ketu'] = pan['ketu']
        vedic_aspects = {'Sun': [7], 'Moon': [7], 'Mercury': [7], 'Venus': [7], 'Mars': [4,7,8], 'Jupiter': [5,7,9], 'Saturn': [3,7,10], 'Rahu': [5,7,9,12], 'Ketu': [5,7,9,12]}
        western_aspects = {'Conjunction': {'angle': 0, 'orb': 8}, 'Sextile': {'angle': 60, 'orb': 6}, 'Square': {'angle': 90, 'orb': 7}, 'Trine': {'angle': 120, 'orb': 7}, 'Opposition': {'angle': 180, 'orb': 8}}
        aspects_on_planets = []
        for target_planet, target_sid in planets_sid.items():
            if target_sid == 0 and target_planet in ['Mercury','Venus','Mars','Jupiter','Saturn']:
                continue
            aspecting_planets = []
            for aspecting_planet, aspecting_sid in planets_sid.items():
                if aspecting_planet == target_planet:
                    continue
                if aspecting_sid == 0 and aspecting_planet in ['Mercury','Venus','Mars','Jupiter','Saturn']:
                    continue
                diff = (aspecting_sid - target_sid) % 360
                house_diff = int((diff // 30) + 1)
                vedic_aspecting = False
                vedic_house = None
                if aspecting_planet in vedic_aspects:
                    if house_diff in vedic_aspects[aspecting_planet]:
                        vedic_aspecting = True
                        vedic_house = house_diff
                western_aspecting = None
                for asp_name, asp_data in western_aspects.items():
                    asp_angle = asp_data['angle']
                    orb = asp_data['orb']
                    sep = min(diff, 360-diff)
                    if abs(diff - asp_angle) <= orb or abs(diff - (360-asp_angle)) <= orb or abs(sep - asp_angle) <= orb:
                        if not (asp_name == 'Conjunction' and sep > orb):
                            if asp_name == 'Conjunction' and sep <= orb:
                                western_aspecting = asp_name
                            elif asp_name != 'Conjunction' and abs(sep - asp_angle) <= orb:
                                western_aspecting = asp_name
                if vedic_aspecting or western_aspecting:
                    aspecting_planets.append({'aspecting_planet': aspecting_planet, 'aspecting_sid': aspecting_sid, 'target_planet': target_planet, 'target_sid': target_sid, 'angular_diff': diff, 'house_diff': house_diff, 'vedic_aspect': vedic_aspecting, 'vedic_house': vedic_house, 'vedic_aspect_text': f"{aspecting_planet} aspects {target_planet} in {house_diff}th house" if vedic_aspecting else "", 'western_aspect': western_aspecting, 'western_text': f"{western_aspecting} ({diff:.1f}°)" if western_aspecting else "", 'orb': abs(diff - (western_aspects[western_aspecting]['angle'] if western_aspecting and western_aspecting in western_aspects else 0)) if western_aspecting else 0})
            aspects_on_planets.append({'planet': target_planet, 'sid': target_sid, 'aspected_by': aspecting_planets, 'total_aspects': len(aspecting_planets), 'benefic_aspects': len([a for a in aspecting_planets if a['aspecting_planet'] in ['Jupiter','Venus','Moon','Mercury']]), 'malefic_aspects': len([a for a in aspecting_planets if a['aspecting_planet'] in ['Saturn','Mars','Rahu','Ketu','Sun']])})
        return {'title': 'Aspects on Planets - Graha Drishti', 'vedic_aspect_rules': vedic_aspects, 'western_aspect_rules': western_aspects, 'table': aspects_on_planets, 'calculation': 'Vedic: All planets 7th, Mars 4/7/8, Jupiter 5/7/9, Saturn 3/7/10, Rahu/Ketu 5/7/9/12. Western: Conjunction 0° orb 8°, Sextile 60° orb 6°, Square 90° orb 7°, Trine 120° orb 7°, Opposition 180° orb 8°'}
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_aspects_on_cusps(jd, panchang, lat, lon):
    """Page 7: Aspects on Cusps (Bhava) table"""
    try:
        pan = panchang
        cusps_trop = []
        cusps_sid = []
        ayan = pan.get('ayanamsa', 23.8)
        try:
            import swisseph as swe
            cusps, ascmc = swe.houses(jd, lat, lon, b'P')
            cusps_trop = list(cusps)
            cusps_sid = [(c - ayan) % 360 for c in cusps_trop]
        except:
            lagna_sid = pan['lagna']['sid']
            for i in range(12):
                cusp_sid = (lagna_sid + i*30) % 360
                cusp_trop = (cusp_sid + ayan) % 360
                cusps_sid.append(cusp_sid)
                cusps_trop.append(cusp_trop)
        planets_sid = {}
        planets_sid['Sun'] = pan['sun']['sid']
        planets_sid['Moon'] = pan['moon']['sid']
        planets_sid['Mercury'] = pan['planets'].get('mercury', {}).get('sid', 0)
        planets_sid['Venus'] = pan['planets'].get('venus', {}).get('sid', 0)
        planets_sid['Mars'] = pan['planets'].get('mars', {}).get('sid', 0)
        planets_sid['Jupiter'] = pan['planets'].get('jupiter', {}).get('sid', 0)
        planets_sid['Saturn'] = pan['planets'].get('saturn', {}).get('sid', 0)
        planets_sid['Rahu'] = pan['rahu']
        planets_sid['Ketu'] = pan['ketu']
        vedic_aspects = {'Sun': [7], 'Moon': [7], 'Mercury': [7], 'Venus': [7], 'Mars': [4,7,8], 'Jupiter': [5,7,9], 'Saturn': [3,7,10], 'Rahu': [5,7,9,12], 'Ketu': [5,7,9,12]}
        aspects_on_cusps = []
        for cusp_idx in range(12):
            cusp_sid = cusps_sid[cusp_idx]
            cusp_trop = cusps_trop[cusp_idx]
            house_num = cusp_idx + 1
            aspecting = []
            for p_name, p_sid in planets_sid.items():
                if p_sid == 0 and p_name in ['Mercury','Venus','Mars','Jupiter','Saturn']:
                    continue
                diff = (p_sid - cusp_sid) % 360
                house_diff = int((diff // 30) + 1)
                if p_name in vedic_aspects and house_diff in vedic_aspects[p_name]:
                    aspecting.append({'planet': p_name, 'planet_sid': p_sid, 'cusp': house_num, 'cusp_sid': cusp_sid, 'house_diff': house_diff, 'aspect_text': f"{p_name} aspects {house_num}th house cusp in {house_diff}th from itself"})
            aspects_on_cusps.append({'house': house_num, 'cusp_sid': cusp_sid, 'cusp_trop': cusp_trop, 'rashi_num': int(cusp_sid // 30) + 1, 'rashi_name': ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"][int(cusp_sid // 30)], 'aspected_by': aspecting, 'total_aspects': len(aspecting)})
        return {'title': 'Aspects on Cusps - Bhava Drishti', 'cusps_sid': cusps_sid, 'cusps_trop': cusps_trop, 'table': aspects_on_cusps, 'calculation': 'Equal houses from Lagna or Placidus cusps via Swiss. Aspects same as Graha Drishti: Mars 4/7/8, Jupiter 5/7/9, Saturn 3/7/10'}
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_sayan_charts(jd, panchang, lat, lon):
    """Page 8: Sayan (Tropical) Lagna Chart + Sayan Cusp Chart"""
    try:
        pan = panchang
        ayan = pan.get('ayanamsa', 23.8)
        planets_trop = {}
        planets_trop['Sun'] = (pan['sun']['sid'] + ayan) % 360
        planets_trop['Moon'] = (pan['moon']['sid'] + ayan) % 360
        planets_trop['Mercury'] = (pan['planets'].get('mercury', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('mercury') else 0
        planets_trop['Venus'] = (pan['planets'].get('venus', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('venus') else 0
        planets_trop['Mars'] = (pan['planets'].get('mars', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('mars') else 0
        planets_trop['Jupiter'] = (pan['planets'].get('jupiter', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('jupiter') else 0
        planets_trop['Saturn'] = (pan['planets'].get('saturn', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('saturn') else 0
        planets_trop['Rahu'] = (pan['rahu'] + ayan) % 360
        planets_trop['Ketu'] = (pan['ketu'] + ayan) % 360
        planets_trop['Uranus'] = (pan['planets'].get('uranus', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('uranus') else 0
        planets_trop['Neptune'] = (pan['planets'].get('neptune', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('neptune') else 0
        planets_trop['Pluto'] = (pan['planets'].get('pluto', {}).get('sid', 0) + ayan) % 360 if pan['planets'].get('pluto') else 0
        planets_sid = {}
        planets_sid['Sun'] = pan['sun']['sid']
        planets_sid['Moon'] = pan['moon']['sid']
        planets_sid['Mercury'] = pan['planets'].get('mercury', {}).get('sid', 0)
        planets_sid['Venus'] = pan['planets'].get('venus', {}).get('sid', 0)
        planets_sid['Mars'] = pan['planets'].get('mars', {}).get('sid', 0)
        planets_sid['Jupiter'] = pan['planets'].get('jupiter', {}).get('sid', 0)
        planets_sid['Saturn'] = pan['planets'].get('saturn', {}).get('sid', 0)
        planets_sid['Rahu'] = pan['rahu']
        planets_sid['Ketu'] = pan['ketu']
        planets_sid['Uranus'] = pan['planets'].get('uranus', {}).get('sid', 0)
        planets_sid['Neptune'] = pan['planets'].get('neptune', {}).get('sid', 0)
        planets_sid['Pluto'] = pan['planets'].get('pluto', {}).get('sid', 0)
        lagna_sid = pan['lagna']['sid']
        lagna_trop = (lagna_sid + ayan) % 360
        cusps_trop = []
        cusps_sid = []
        try:
            import swisseph as swe
            cusps, ascmc = swe.houses(jd, lat, lon, b'P')
            cusps_trop = list(cusps)
            cusps_sid = [(c - ayan) % 360 for c in cusps_trop]
            lagna_trop_calc = ascmc[0] % 360
            lagna_sid_calc = (lagna_trop_calc - ayan) % 360
            lagna_trop = lagna_trop_calc
            lagna_sid = lagna_sid_calc
        except:
            for i in range(12):
                c_sid = (lagna_sid + i*30) % 360
                c_trop = (c_sid + ayan) % 360
                cusps_sid.append(c_sid)
                cusps_trop.append(c_trop)
        rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"]
        western_rashi = ["Aries","Taurus","Gemini","Cancer","Leo","Virgo","Libra","Scorpio","Sagittarius","Capricorn","Aquarius","Pisces"]
        sayan_lagna_planets = []
        for p_name in ['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Rahu','Ketu','Uranus','Neptune','Pluto','Lagna']:
            if p_name == 'Lagna':
                trop = lagna_trop
                sid = lagna_sid
            else:
                trop = planets_trop.get(p_name, 0)
                sid = planets_sid.get(p_name, 0)
                if trop == 0 and p_name in ['Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto']:
                    continue
            rashi_num_trop = int(trop // 30) + 1
            rashi_num_sid = int(sid // 30) + 1
            deg_trop = trop % 30
            deg_sid = sid % 30
            d_t, m_t, s_t = deg_to_dms(deg_trop)
            d_s, m_s, s_s = deg_to_dms(deg_sid)
            house_trop = (rashi_num_trop - int(lagna_trop // 30) - 1 + 12) % 12 + 1 if p_name != 'Lagna' else 1
            sayan_lagna_planets.append({'planet': p_name, 'sayan_trop_deg': trop, 'sayan_rashi_num': rashi_num_trop, 'sayan_rashi_name': western_rashi[rashi_num_trop-1], 'sayan_rashi_name_hindi': rashi_names[rashi_num_trop-1], 'nirayana_sid_deg': sid, 'nirayana_rashi_num': rashi_num_sid, 'nirayana_rashi_name': rashi_names[rashi_num_sid-1], 'sayan_ansh': d_t, 'sayan_kala': m_t, 'sayan_vikala': int(s_t), 'nirayana_ansh': d_s, 'nirayana_kala': m_s, 'nirayana_vikala': int(s_s), 'sayan_dms': f"{d_t}°{m_t}'{int(s_t)}s", 'nirayana_dms': f"{d_s}°{m_s}'{int(s_s)}s", 'house_sayan': house_trop, 'ayanamsa': ayan})
        sayan_cusp_chart = []
        for i in range(12):
            c_trop = cusps_trop[i] if i < len(cusps_trop) else (lagna_trop + i*30) % 360
            c_sid = cusps_sid[i] if i < len(cusps_sid) else (lagna_sid + i*30) % 360
            rashi_num_trop = int(c_trop // 30) + 1
            rashi_num_sid = int(c_sid // 30) + 1
            deg_trop = c_trop % 30
            deg_sid = c_sid % 30
            d_t, m_t, s_t = deg_to_dms(deg_trop)
            d_s, m_s, s_s = deg_to_dms(deg_sid)
            planets_in_house = []
            for p in sayan_lagna_planets:
                if p['planet'] == 'Lagna':
                    continue
                if p['house_sayan'] == i+1:
                    planets_in_house.append(p['planet'])
            sayan_cusp_chart.append({'house': i+1, 'cusp_sayan_trop': c_trop, 'cusp_sayan_rashi_num': rashi_num_trop, 'cusp_sayan_rashi': western_rashi[rashi_num_trop-1], 'cusp_sayan_rashi_hindi': rashi_names[rashi_num_trop-1], 'cusp_nirayana_sid': c_sid, 'cusp_nirayana_rashi_num': rashi_num_sid, 'cusp_nirayana_rashi': rashi_names[rashi_num_sid-1], 'sayan_ansh': d_t, 'sayan_kala': m_t, 'sayan_vikala': int(s_t), 'nirayana_ansh': d_s, 'nirayana_kala': m_s, 'nirayana_vikala': int(s_s), 'sayan_dms': f"{d_t}°{m_t}'{int(s_t)}s", 'nirayana_dms': f"{d_s}°{m_s}'{int(s_s)}s", 'planets_in_house': planets_in_house})
        return {'title': 'Sayan Charts - Tropical - Western', 'ayanamsa': ayan, 'sayan_lagna_trop': lagna_trop, 'nirayana_lagna_sid': lagna_sid, 'sayan_lagna_chart': {'title': 'Sayan Lagna Chart - Planets in Sayan Houses/Rashis', 'lagna_trop': lagna_trop, 'lagna_sid': lagna_sid, 'planets_table': sayan_lagna_planets, 'note': 'Sayan = Nirayana + Ayanamsa. Western zodiac. House = (Planet Rashi - Lagna Rashi) mod 12 +1'}, 'sayan_cusp_chart': {'title': 'Sayan Cusp Chart - House Cusps in Sayan/Nirayana', 'cusps_trop': cusps_trop, 'cusps_sid': cusps_sid, 'table': sayan_cusp_chart, 'note': 'Cusps via Swiss houses Placidus or Equal houses from Lagna'}, 'calculation': f'Sayan Tropical = Nirayana Sidereal + Ayanamsa ({ayan:.4f}°). Ayanamsa via swe.get_ayanamsa_ut() Lahiri exact'}
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_yearly_and_progression(jd, panchang, lat, lon, birth_year=None):
    """Page 8: Yearly Calculations (Varshapal/Tajika) + Progression Chart"""
    try:
        pan = panchang
        def jd_to_date(jd_val):
            jd_val += 0.5
            Z = int(jd_val)
            F = jd_val - Z
            if Z < 2299161:
                A = Z
            else:
                alpha = int((Z - 1867216.25) / 36524.25)
                A = Z + 1 + alpha - alpha // 4
            B = A + 1524
            C = int((B - 122.1) / 365.25)
            D = int(365.25 * C)
            E = int((B - D) / 30.6001)
            day = B - D - int(30.6001 * E) + F
            month = E - 1 if E < 14 else E - 13
            year = C - 4716 if month > 2 else C - 4715
            return int(year), int(month), int(day)
        birth_y, birth_m, birth_d = jd_to_date(jd)
        if birth_year is None:
            birth_year = birth_y
        yearly_charts = []
        for year_offset in range(0, 5):
            target_year = birth_year + year_offset
            jd_approx = jd + year_offset * 365.2422
            try:
                pan_year = full_panchang(jd_approx, lat, lon)
                sun_sid_birth = pan['sun']['sid']
                for delta in range(-2, 3):
                    jd_test = jd_approx + delta
                    pan_test = full_panchang(jd_test, lat, lon)
                    if abs((pan_test['sun']['sid'] - sun_sid_birth + 360) % 360) < 1.0:
                        jd_approx = jd_test
                        pan_year = pan_test
                        break
                lagna_sid = pan['lagna']['sid']
                muntha_sid = (lagna_sid + year_offset * 30) % 360
                muntha_rashi = int(muntha_sid // 30) + 1
                varsha_lagna_sid = pan_year['lagna']['sid']
                varsha_lagna_rashi = int(varsha_lagna_sid // 30) + 1
                yearly_charts.append({'year': target_year, 'year_offset': year_offset, 'jd_solar_return': jd_approx, 'sun_sid_birth': sun_sid_birth, 'sun_sid_return': pan_year['sun']['sid'], 'varsha_lagna_sid': varsha_lagna_sid, 'varsha_lagna_rashi_num': varsha_lagna_rashi, 'varsha_lagna_rashi': ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"][varsha_lagna_rashi-1], 'muntha_sid': muntha_sid, 'muntha_rashi_num': muntha_rashi, 'muntha_rashi': ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"][muntha_rashi-1], 'planets_sid': {'Sun': pan_year['sun']['sid'], 'Moon': pan_year['moon']['sid'], 'Mercury': pan_year['planets'].get('mercury',{}).get('sid',0), 'Venus': pan_year['planets'].get('venus',{}).get('sid',0), 'Mars': pan_year['planets'].get('mars',{}).get('sid',0), 'Jupiter': pan_year['planets'].get('jupiter',{}).get('sid',0), 'Saturn': pan_year['planets'].get('saturn',{}).get('sid',0)}})
            except Exception as e_year:
                yearly_charts.append({'year': target_year, 'error': str(e_year)})
        progression_charts = []
        for year_offset in range(0, 5):
            jd_prog = jd + year_offset
            try:
                pan_prog = full_panchang(jd_prog, lat, lon)
                sun_sid_birth = pan['sun']['sid']
                sun_sid_prog = pan_prog['sun']['sid']
                solar_arc = (sun_sid_prog - sun_sid_birth) % 360
                if solar_arc > 180:
                    solar_arc -= 360
                progression_charts.append({'year_offset': year_offset, 'age': year_offset, 'jd_progression': jd_prog, 'method': 'Secondary: 1 day = 1 year', 'sun_sid_birth': sun_sid_birth, 'sun_sid_progressed': pan_prog['sun']['sid'], 'solar_arc_deg': solar_arc, 'moon_sid_progressed': pan_prog['moon']['sid'], 'lagna_sid_progressed': pan_prog['lagna']['sid'], 'planets_progressed': {'Sun': pan_prog['sun']['sid'], 'Moon': pan_prog['moon']['sid'], 'Mercury': pan_prog['planets'].get('mercury',{}).get('sid',0), 'Venus': pan_prog['planets'].get('venus',{}).get('sid',0), 'Mars': pan_prog['planets'].get('mars',{}).get('sid',0), 'Jupiter': pan_prog['planets'].get('jupiter',{}).get('sid',0), 'Saturn': pan_prog['planets'].get('saturn',{}).get('sid',0)}, 'interpretation': f"Age {year_offset}: Solar Arc {solar_arc:.2f}°, Moon progressed {pan_prog['moon']['sid']:.2f}°"})
            except Exception as e_prog:
                progression_charts.append({'year_offset': year_offset, 'error': str(e_prog)})
        return {'title': 'Yearly Calculations & Progression Chart', 'birth_year': birth_year, 'yearly_varshapal': {'title': 'Yearly Calculations - Varshapal - Tajika - Solar Return', 'description': 'Varshapal: Solar return when Sun returns to birth sidereal longitude. Muntha progresses 1 rashi/year. Varsha Lagna = Lagna at return. Tajika Yogas, Sahams, Tripataki Chakra', 'charts': yearly_charts, 'calculation': 'Solar return JD = Birth JD + n*365.2422, fine tuned to Sun sid = birth Sun sid. Muntha = (Birth Lagna + n*30°) %360. Varsha Lagna via Swiss houses'}, 'progression_chart': {'title': 'Progression Chart - Secondary & Solar Arc', 'description': 'Secondary progression: 1 day after birth = 1 year of life. Solar Arc: 1° Sun movement = 1 year. Shows progressed Sun, Moon, Lagna, planets', 'charts': progression_charts, 'calculation': 'Secondary: JD_prog = Birth JD + age_in_years (days). Solar Arc = (Prog Sun - Birth Sun). Progressed positions via Swiss full_panchang'}}
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}



def get_kp_sub_sub_sub_lord(planet_sid):
    """
    KP 4th level - Sub-Sub-Sub Lord (SSS Lord)
    Nakshatra -> Sub -> Sub-Sub -> Sub-Sub-Sub
    Each level divided proportionally by Vimshottari years
    """
    try:
        nak_lord_years = {"Ketu":7,"Venus":20,"Sun":6,"Moon":10,"Mars":7,"Rahu":18,"Jupiter":16,"Saturn":19,"Mercury":17}
        nak_lords_order = ["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"]
        
        # Level 1: Nakshatra
        nak_deg = planet_sid % 13.333333
        nak_num = int(planet_sid / 13.333333) + 1
        nak_lord = get_nakshatra_lord(nak_num)
        
        # Level 2: Sub Lord
        sub_deg = 0
        nak_lord_idx = nak_lords_order.index(nak_lord)
        sub_lord = nak_lord
        sub_size = 13.333333
        deg_in_sub = nak_deg
        
        for i in range(9):
            idx = (nak_lord_idx + i) % 9
            lord = nak_lords_order[idx]
            s_size = 13.333333 * nak_lord_years[lord] / 120.0
            if nak_deg < sub_deg + s_size:
                sub_lord = lord
                sub_size = s_size
                deg_in_sub = nak_deg - sub_deg
                break
            sub_deg += s_size
        
        # Level 3: Sub-Sub Lord
        sub_sub_deg = 0
        sub_lord_idx = nak_lords_order.index(sub_lord)
        sub_sub_lord = sub_lord
        sub_sub_size = sub_size
        deg_in_sub_sub = deg_in_sub
        
        for i in range(9):
            idx = (sub_lord_idx + i) % 9
            lord = nak_lords_order[idx]
            ss_size = sub_size * nak_lord_years[lord] / 120.0
            if deg_in_sub < sub_sub_deg + ss_size:
                sub_sub_lord = lord
                sub_sub_size = ss_size
                deg_in_sub_sub = deg_in_sub - sub_sub_deg
                break
            sub_sub_deg += ss_size
        
        # Level 4: Sub-Sub-Sub Lord
        sub_sub_sub_deg = 0
        sub_sub_lord_idx = nak_lords_order.index(sub_sub_lord)
        sub_sub_sub_lord = sub_sub_lord
        
        for i in range(9):
            idx = (sub_sub_lord_idx + i) % 9
            lord = nak_lords_order[idx]
            sss_size = sub_sub_size * nak_lord_years[lord] / 120.0
            if deg_in_sub_sub < sub_sub_sub_deg + sss_size:
                sub_sub_sub_lord = lord
                break
            sub_sub_sub_deg += sss_size
        
        return nak_lord, sub_lord, sub_sub_lord, sub_sub_sub_lord
    except:
        return "Ketu", "Ketu", "Ketu", "Ketu"

def calculate_kp_cusps_and_planets(jd, panchang, lat, lon):
    """
    KP System - Calculate Cusps (Placidus) and Planets with KP details
    KP uses Placidus house system - Cusps are Bhava beginning
    """
    try:
        import swisseph as swe
        pan = panchang
        ayan = pan.get('ayanamsa', 23.8)
        
        # Get Placidus cusps
        try:
            cusps, ascmc = swe.houses(jd, lat, lon, b'P')  # Placidus
            # cusps[1..12] - ascmc[0]=Asc, ascmc[1]=MC
            cusps_sid = []
            for i in range(12):
                # cusps[0] is for house 1? Actually cusps[1] is house 1 in Swiss? Let's check
                # Swiss returns cusps[0]=0, cusps[1]=house1, ... cusps[12]=house12
                # But array is 0-12, with 0 unused? Actually Python returns 13 elements? Let's handle
                if i+1 < len(cusps):
                    c_trop = cusps[i+1] % 360
                else:
                    c_trop = (ascmc[0] + i*30) % 360
                c_sid = (c_trop - ayan) % 360
                cusps_sid.append(c_sid)
        except:
            # Fallback equal houses
            lagna_sid = pan['lagna']['sid']
            cusps_sid = [(lagna_sid + i*30) % 360 for i in range(12)]
        
        # Planets sidereal
        planets_sid = {}
        planets_sid['Sun'] = pan['sun']['sid']
        planets_sid['Moon'] = pan['moon']['sid']
        planets_sid['Mercury'] = pan['planets'].get('mercury', {}).get('sid', 0)
        planets_sid['Venus'] = pan['planets'].get('venus', {}).get('sid', 0)
        planets_sid['Mars'] = pan['planets'].get('mars', {}).get('sid', 0)
        planets_sid['Jupiter'] = pan['planets'].get('jupiter', {}).get('sid', 0)
        planets_sid['Saturn'] = pan['planets'].get('saturn', {}).get('sid', 0)
        planets_sid['Rahu'] = pan['rahu']
        planets_sid['Ketu'] = pan['ketu']
        planets_sid['Uranus'] = pan['planets'].get('uranus', {}).get('sid', 0)
        planets_sid['Neptune'] = pan['planets'].get('neptune', {}).get('sid', 0)
        planets_sid['Pluto'] = pan['planets'].get('pluto', {}).get('sid', 0)
        
        # Calculate KP details for each cusp
        rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"]
        nak_names = ["Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra","Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni","Uttara Phalguni","Hasta","Chitra","Swati","Vishakha","Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha","Shravana","Dhanishta","Shatabhisha","Purva Bhadrapada","Uttara Bhadrapada","Revati"]
        
        cusp_details = []
        for i in range(12):
            cusp_sid = cusps_sid[i]
            rashi_num = int(cusp_sid // 30) + 1
            deg_in_rashi = cusp_sid % 30
            d, m, s = deg_to_dms(deg_in_rashi)
            
            nak_num = int(cusp_sid / 13.333333) + 1
            nak_name = nak_names[nak_num-1]
            star_lord, sub_lord, sub_sub_lord, sub_sub_sub_lord = get_kp_sub_sub_sub_lord(cusp_sid)
            
            cusp_details.append({
                'cusp': i+1,
                'sid_deg': cusp_sid,
                'rashi_num': rashi_num,
                'rashi_name': rashi_names[rashi_num-1],
                'ansh': d,
                'kala': m,
                'vikala': int(s),
                'dms': f"{d}°{m}'{int(s)}s",
                'deg_in_rashi': deg_in_rashi,
                'nakshatra_num': nak_num,
                'nakshatra_name': nak_name,
                'nakshatra_lord': star_lord,
                'sub_lord': sub_lord,
                'sub_sub_lord': sub_sub_lord,
                'sub_sub_sub_lord': sub_sub_sub_lord,
                'star_lord': star_lord,
                'rashi_lord': get_rashi_lord(rashi_num)
            })
        
        # Calculate KP details for each planet
        planet_details = []
        for p_name, p_sid in planets_sid.items():
            if p_sid == 0 and p_name in ['Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto']:
                continue
            
            rashi_num = int(p_sid // 30) + 1
            deg_in_rashi = p_sid % 30
            d, m, s = deg_to_dms(deg_in_rashi)
            
            nak_num = int(p_sid / 13.333333) + 1
            nak_name = nak_names[nak_num-1]
            star_lord, sub_lord, sub_sub_lord, sub_sub_sub_lord = get_kp_sub_sub_sub_lord(p_sid)
            
            # House from Lagna (KP uses cusp-based, but simplified to rashi-based for now)
            # In KP, planet in house based on cusp: if planet sid between cusp[i] and cusp[i+1], then house i+1
            house = 1
            for h in range(12):
                c1 = cusps_sid[h]
                c2 = cusps_sid[(h+1)%12]
                # Handle 0° crossing
                # Check if p_sid is between c1 and c2
                # Normalize
                # If c2 < c1 (crosses 0), then planet is in house if p_sid >= c1 or p_sid < c2
                if c2 < c1:
                    if p_sid >= c1 or p_sid < c2:
                        house = h+1
                        break
                else:
                    if c1 <= p_sid < c2:
                        house = h+1
                        break
            
            planet_details.append({
                'planet': p_name,
                'sid_deg': p_sid,
                'rashi_num': rashi_num,
                'rashi_name': rashi_names[rashi_num-1],
                'ansh': d,
                'kala': m,
                'vikala': int(s),
                'dms': f"{d}°{m}'{int(s)}s",
                'deg_in_rashi': deg_in_rashi,
                'nakshatra_num': nak_num,
                'nakshatra_name': nak_name,
                'nakshatra_lord': star_lord,
                'star_lord': star_lord,
                'sub_lord': sub_lord,
                'sub_sub_lord': sub_sub_lord,
                'sub_sub_sub_lord': sub_sub_sub_lord,
                'rashi_lord': get_rashi_lord(rashi_num),
                'house': house
            })
        
        return {
            'cusps_sid': cusps_sid,
            'cusp_details': cusp_details,
            'planets_sid': planets_sid,
            'planet_details': planet_details
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_kp_significators(jd, panchang, lat, lon, kp_data):
    """
    Page 10: K.P. Significator Planets and Cusps tables
    KP Significator rules:
    1. Planets in constellation (star) of occupant
    2. Occupant of house
    3. Owner of house
    4. Planets in star of owner
    5. 2nd level significators, etc
    Simplified: Strong significators are planets whose star lord is occupant or owner
    """
    try:
        pan = panchang
        cusps_sid = kp_data.get('cusps_sid', [])
        cusp_details = kp_data.get('cusp_details', [])
        planet_details = kp_data.get('planet_details', [])
        
        rashi_lords = {1:"Mars",2:"Venus",3:"Mercury",4:"Moon",5:"Sun",6:"Mercury",7:"Venus",8:"Mars",9:"Jupiter",10:"Saturn",11:"Saturn",12:"Jupiter"}
        
        # For each house, find significators
        significator_planets = {}  # house -> list of planets
        significator_cusps = {}    # planet -> list of houses it signifies
        
        # Initialize
        for house in range(1,13):
            significator_planets[house] = []
        
        for planet_info in planet_details:
            p_name = planet_info['planet']
            if p_name in ['Rahu','Ketu']:
                continue
            significator_cusps[p_name] = []
        
        # Rule 1: Planet in house is significator of that house
        for planet_info in planet_details:
            p_name = planet_info['planet']
            house = planet_info['house']
            if house not in significator_planets:
                significator_planets[house] = []
            significator_planets[house].append({
                'planet': p_name,
                'level': 1,
                'reason': f"Occupant of {house}th house",
                'type': 'Occupant'
            })
            if p_name in significator_cusps:
                significator_cusps[p_name].append({
                    'house': house,
                    'level': 1,
                    'reason': f"Occupant of {house}"
                })
        
        # Rule 2: Owner of house is significator
        lagna_sid = pan['lagna']['sid']
        lagna_rashi = int(lagna_sid // 30) + 1
        
        for house in range(1,13):
            rashi_num = (lagna_rashi + house - 1 - 1) % 12 + 1
            owner = rashi_lords[rashi_num]
            
            significator_planets[house].append({
                'planet': owner,
                'level': 2,
                'reason': f"Owner of {house}th house (Rashi {rashi_num})",
                'type': 'Owner'
            })
            
            if owner in significator_cusps:
                significator_cusps[owner].append({
                    'house': house,
                    'level': 2,
                    'reason': f"Owner of {house}th"
                })
        
        # Rule 3: Planets in star of occupant are significators
        # For each house, find occupant, then find planets whose star lord is occupant's star lord? Or occupant itself?
        # KP rule: Planet A signifies house B if star lord of A is occupant of B or owner of B
        
        # Build map: star lord -> planets in that star
        star_to_planets = {}
        for planet_info in planet_details:
            star = planet_info['star_lord']
            if star not in star_to_planets:
                star_to_planets[star] = []
            star_to_planets[star].append(planet_info['planet'])
        
        for house in range(1,13):
            # Get occupants of this house
            occupants = [p for p in planet_details if p['house'] == house]
            for occupant in occupants:
                star_lord_of_occupant = occupant['star_lord']
                # Planets in star of occupant? Actually planets whose star lord = occupant? No
                # Correct KP: If planet X is in star of Y, and Y is occupant of house Z, then X signifies Z
                # So find planets whose star lord = occupant's name? No, star lord is like Jupiter, not planet name
                # Let's interpret: Planet's star lord is e.g., Jupiter. If Jupiter is occupant, then planet signifies?
                # Simplified: Planet signifies house if its star lord is occupant of that house or owner of that house
                
                # For each planet, check if its star lord is occupant of this house
                for planet_info in planet_details:
                    p_name = planet_info['planet']
                    star_lord = planet_info['star_lord']
                    # If star_lord is same as occupant's planet name, then p signifies house
                    if star_lord == occupant['planet']:
                        significator_planets[house].append({
                            'planet': p_name,
                            'level': 3,
                            'reason': f"In star of {occupant['planet']} who is occupant of {house}",
                            'type': 'Star of Occupant'
                        })
                        if p_name in significator_cusps:
                            significator_cusps[p_name].append({
                                'house': house,
                                'level': 3,
                                'reason': f"Star lord {star_lord} is occupant of {house}"
                            })
        
        # Rule 4: Planets in star of owner
        for house in range(1,13):
            rashi_num = (lagna_rashi + house - 1 - 1) % 12 + 1
            owner = rashi_lords[rashi_num]
            # Find planets whose star lord = owner
            for planet_info in planet_details:
                p_name = planet_info['planet']
                star_lord = planet_info['star_lord']
                if star_lord == owner:
                    significator_planets[house].append({
                        'planet': p_name,
                        'level': 4,
                        'reason': f"In star of {owner} who is owner of {house}",
                        'type': 'Star of Owner'
                    })
                    if p_name in significator_cusps:
                        significator_cusps[p_name].append({
                            'house': house,
                            'level': 4,
                            'reason': f"Star lord {owner} is owner of {house}"
                        })
        
        # Remove duplicates and sort by level
        for house in significator_planets:
            # Deduplicate by planet
            seen = {}
            unique = []
            for sig in significator_planets[house]:
                p = sig['planet']
                if p not in seen or sig['level'] < seen[p]['level']:
                    seen[p] = sig
            # Convert to list
            unique = list(seen.values())
            # Sort by level
            unique.sort(key=lambda x: x['level'])
            significator_planets[house] = unique
        
        for planet in significator_cusps:
            seen = {}
            unique = []
            for sig in significator_cusps[planet]:
                h = sig['house']
                if h not in seen or sig['level'] < seen[h]['level']:
                    seen[h] = sig
            unique = list(seen.values())
            unique.sort(key=lambda x: (x['level'], x['house']))
            significator_cusps[planet] = unique
        
        # Build tables
        planet_sig_table = []
        for house in range(1,13):
            sigs = significator_planets.get(house, [])
            planet_sig_table.append({
                'house': house,
                'significators': sigs,
                'planets_list': [s['planet'] for s in sigs],
                'count': len(sigs)
            })
        
        cusp_sig_table = []
        for planet in ['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Rahu','Ketu','Uranus','Neptune','Pluto']:
            if planet not in significator_cusps:
                continue
            sigs = significator_cusps.get(planet, [])
            if not sigs:
                continue
            cusp_sig_table.append({
                'planet': planet,
                'signifies_houses': sigs,
                'houses_list': [s['house'] for s in sigs],
                'count': len(sigs)
            })
        
        return {
            'title': 'K.P. Significators',
            'significator_planets_table': planet_sig_table,
            'significator_cusps_table': cusp_sig_table,
            'calculation': 'Level 1: Occupant, Level 2: Owner, Level 3: Star of Occupant, Level 4: Star of Owner. Sorted by level strength'
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_kp_four_step(jd, panchang, lat, lon, kp_data):
    """
    Page 11: K.P. Four Step for Planets and Cusps
    Four Step Theory: Each planet's signification is determined by 4 levels:
    1. Planet's star lord signifies houses
    2. Planet's sub lord signifies houses
    3. Planet's sub-sub lord
    4. Planet's sub-sub-sub lord
    Combined significations give final result
    """
    try:
        cusp_details = kp_data.get('cusp_details', [])
        planet_details = kp_data.get('planet_details', [])
        
        # For Four Step, we need significations of star lord, sub lord, etc
        # First, build star lord to houses mapping from previous significator calculation
        # Simplified: Use cusp owner + occupant logic for star lord significations
        
        rashi_lords = {1:"Mars",2:"Venus",3:"Mercury",4:"Moon",5:"Sun",6:"Mercury",7:"Venus",8:"Mars",9:"Jupiter",10:"Saturn",11:"Saturn",12:"Jupiter"}
        lagna_sid = panchang['lagna']['sid']
        lagna_rashi = int(lagna_sid // 30) + 1
        
        # Build lord to houses mapping
        lord_to_houses = {}
        for house in range(1,13):
            rashi_num = (lagna_rashi + house - 1 - 1) % 12 + 1
            owner = rashi_lords[rashi_num]
            if owner not in lord_to_houses:
                lord_to_houses[owner] = []
            lord_to_houses[owner].append(house)
        
        # Planet to house (occupant)
        planet_to_house = {}
        for p_info in planet_details:
            planet_to_house[p_info['planet']] = p_info['house']
        
        four_step_planets = []
        for p_info in planet_details:
            p_name = p_info['planet']
            if p_name == 'Lagna':
                continue
            
            star_lord = p_info['star_lord']
            sub_lord = p_info['sub_lord']
            sub_sub_lord = p_info['sub_sub_lord']
            sub_sub_sub_lord = p_info['sub_sub_sub_lord']
            
            # Get houses signified by each lord
            # Star lord signifies: houses owned by star lord + house where star lord is occupant
            def get_houses_signified_by_planet(planet_name):
                houses = []
                # Owned houses
                if planet_name in lord_to_houses:
                    houses.extend(lord_to_houses[planet_name])
                # House occupied
                if planet_name in planet_to_house:
                    houses.append(planet_to_house[planet_name])
                return list(set(houses))
            
            star_signifies = get_houses_signified_by_planet(star_lord)
            sub_signifies = get_houses_signified_by_planet(sub_lord)
            sub_sub_signifies = get_houses_signified_by_planet(sub_sub_lord)
            sub_sub_sub_signifies = get_houses_signified_by_planet(sub_sub_sub_lord)
            
            # Combined significations - Four Step theory says final result is based on sub lord, but star lord shows source
            # Level 1 (star) - Source, Level 2 (sub) - Result, Level 3 (sub-sub) - Confirmation, Level 4 (sub-sub-sub) - Final
            combined = list(set(star_signifies + sub_signifies + sub_sub_signifies + sub_sub_sub_signifies))
            combined.sort()
            
            four_step_planets.append({
                'planet': p_name,
                'sid_deg': p_info['sid_deg'],
                'rashi': p_info['rashi_name'],
                'ansh': p_info['ansh'],
                'kala': p_info['kala'],
                'vikala': p_info['vikala'],
                'house': p_info['house'],
                'star_lord': star_lord,
                'sub_lord': sub_lord,
                'sub_sub_lord': sub_sub_lord,
                'sub_sub_sub_lord': sub_sub_sub_lord,
                'star_signifies': star_signifies,
                'sub_signifies': sub_signifies,
                'sub_sub_signifies': sub_sub_signifies,
                'sub_sub_sub_signifies': sub_sub_sub_signifies,
                'combined_signifies': combined,
                'four_step_text': f"{p_name} in {p_info['nakshatra_name']} star of {star_lord}, sub of {sub_lord}, sub-sub of {sub_sub_lord}, sub-sub-sub of {sub_sub_sub_lord}",
                'result_houses': sub_signifies,  # In KP, sub lord gives result
                'source_houses': star_signifies
            })
        
        four_step_cusps = []
        for c_info in cusp_details:
            cusp_num = c_info['cusp']
            star_lord = c_info['star_lord']
            sub_lord = c_info['sub_lord']
            sub_sub_lord = c_info['sub_sub_lord']
            sub_sub_sub_lord = c_info['sub_sub_sub_lord']
            
            def get_houses_signified(planet_name):
                houses = []
                if planet_name in lord_to_houses:
                    houses.extend(lord_to_houses[planet_name])
                if planet_name in planet_to_house:
                    houses.append(planet_to_house[planet_name])
                return list(set(houses))
            
            star_signifies = get_houses_signified(star_lord)
            sub_signifies = get_houses_signified(sub_lord)
            sub_sub_signifies = get_houses_signified(sub_sub_lord)
            sub_sub_sub_signifies = get_houses_signified(sub_sub_sub_lord)
            combined = list(set(star_signifies + sub_signifies + sub_sub_signifies + sub_sub_sub_signifies))
            combined.sort()
            
            four_step_cusps.append({
                'cusp': cusp_num,
                'sid_deg': c_info['sid_deg'],
                'rashi': c_info['rashi_name'],
                'ansh': c_info['ansh'],
                'kala': c_info['kala'],
                'vikala': c_info['vikala'],
                'star_lord': star_lord,
                'sub_lord': sub_lord,
                'sub_sub_lord': sub_sub_lord,
                'sub_sub_sub_lord': sub_sub_sub_lord,
                'star_signifies': star_signifies,
                'sub_signifies': sub_signifies,
                'sub_sub_signifies': sub_sub_signifies,
                'sub_sub_sub_signifies': sub_sub_sub_signifies,
                'combined_signifies': combined,
                'four_step_text': f"Cusp {cusp_num} in {c_info['nakshatra_name']} star of {star_lord}, sub {sub_lord}, sub-sub {sub_sub_lord}, sub-sub-sub {sub_sub_sub_lord}",
                'result_houses': sub_signifies
            })
        
        return {
            'title': 'K.P. Four Step Theory',
            'four_step_planets_table': four_step_planets,
            'four_step_cusps_table': four_step_cusps,
            'calculation': 'Four Step: Star lord = Source, Sub lord = Result, Sub-Sub = Confirmation, Sub-Sub-Sub = Final. Each lord signifies houses owned + occupied. Combined = All 4 levels'
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_kp_fav_unfav_aspects(jd, panchang, lat, lon, kp_data):
    """
    Page 12: Fav-Unfav aspects for Planets and Cusps
    In KP, favorable aspects are from benefic planets and from planets signifying good houses
    """
    try:
        planet_details = kp_data.get('planet_details', [])
        cusp_details = kp_data.get('cusp_details', [])
        
        # Define benefic/malefic naturally
        natural_benefic = ['Jupiter','Venus','Moon','Mercury']
        natural_malefic = ['Saturn','Mars','Sun','Rahu','Ketu']
        
        # For each planet, check aspects from other planets
        # Use Vedic aspects: Mars 4/7/8, Jupiter 5/7/9, Saturn 3/7/10, All 7th
        
        vedic_aspects = {
            'Sun': [7], 'Moon': [7], 'Mercury': [7], 'Venus': [7],
            'Mars': [4,7,8], 'Jupiter': [5,7,9], 'Saturn': [3,7,10],
            'Rahu': [5,7,9,12], 'Ketu': [5,7,9,12]
        }
        
        fav_unfav_planets = []
        for target_info in planet_details:
            target_name = target_info['planet']
            target_house = target_info['house']
            target_sid = target_info['sid_deg']
            
            fav_aspects = []
            unfav_aspects = []
            
            for aspecting_info in planet_details:
                asp_name = aspecting_info['planet']
                if asp_name == target_name:
                    continue
                asp_sid = aspecting_info['sid_deg']
                asp_house = aspecting_info['house']
                
                # Calculate house difference
                diff = (asp_sid - target_sid) % 360
                house_diff = int((diff // 30) + 1)
                
                # Check if aspects
                if asp_name in vedic_aspects and house_diff in vedic_aspects[asp_name]:
                    # Determine fav/unfav
                    # If aspecting planet is natural benefic and signifies good houses (1,2,3,5,9,10,11) then fav
                    # If malefic and signifies bad houses (6,8,12) then unfav
                    
                    # Simplified: Benefic aspecting = Fav, Malefic = Unfav, but also consider house
                    if asp_name in natural_benefic:
                        fav_aspects.append({
                            'aspecting_planet': asp_name,
                            'aspecting_house': asp_house,
                            'target_planet': target_name,
                            'target_house': target_house,
                            'house_diff': house_diff,
                            'type': 'Benefic Aspect',
                            'nature': 'Favorable',
                            'text': f"{asp_name} (Benefic) aspects {target_name} in {house_diff}th house - Favorable"
                        })
                    else:
                        unfav_aspects.append({
                            'aspecting_planet': asp_name,
                            'aspecting_house': asp_house,
                            'target_planet': target_name,
                            'target_house': target_house,
                            'house_diff': house_diff,
                            'type': 'Malefic Aspect',
                            'nature': 'Unfavorable',
                            'text': f"{asp_name} (Malefic) aspects {target_name} in {house_diff}th house - Unfavorable"
                        })
            
            fav_unfav_planets.append({
                'planet': target_name,
                'house': target_house,
                'sid_deg': target_sid,
                'rashi': target_info['rashi_name'],
                'ansh': target_info['ansh'],
                'kala': target_info['kala'],
                'vikala': target_info['vikala'],
                'fav_aspects': fav_aspects,
                'unfav_aspects': unfav_aspects,
                'total_fav': len(fav_aspects),
                'total_unfav': len(unfav_aspects),
                'net_rating': len(fav_aspects) - len(unfav_aspects)
            })
        
        fav_unfav_cusps = []
        for cusp_info in cusp_details:
            cusp_num = cusp_info['cusp']
            cusp_sid = cusp_info['sid_deg']
            
            fav_aspects = []
            unfav_aspects = []
            
            for aspecting_info in planet_details:
                asp_name = aspecting_info['planet']
                asp_sid = aspecting_info['sid_deg']
                asp_house = aspecting_info['house']
                
                diff = (asp_sid - cusp_sid) % 360
                house_diff = int((diff // 30) + 1)
                
                if asp_name in vedic_aspects and house_diff in vedic_aspects[asp_name]:
                    if asp_name in natural_benefic:
                        fav_aspects.append({
                            'aspecting_planet': asp_name,
                            'aspecting_house': asp_house,
                            'target_cusp': cusp_num,
                            'house_diff': house_diff,
                            'type': 'Benefic',
                            'nature': 'Favorable',
                            'text': f"{asp_name} benefic aspects {cusp_num}th cusp"
                        })
                    else:
                        unfav_aspects.append({
                            'aspecting_planet': asp_name,
                            'aspecting_house': asp_house,
                            'target_cusp': cusp_num,
                            'house_diff': house_diff,
                            'type': 'Malefic',
                            'nature': 'Unfavorable',
                            'text': f"{asp_name} malefic aspects {cusp_num}th cusp"
                        })
            
            fav_unfav_cusps.append({
                'cusp': cusp_num,
                'sid_deg': cusp_sid,
                'rashi': cusp_info['rashi_name'],
                'ansh': cusp_info['ansh'],
                'kala': cusp_info['kala'],
                'vikala': cusp_info['vikala'],
                'fav_aspects': fav_aspects,
                'unfav_aspects': unfav_aspects,
                'total_fav': len(fav_aspects),
                'total_unfav': len(unfav_aspects),
                'net_rating': len(fav_aspects) - len(unfav_aspects)
            })
        
        return {
            'title': 'Fav-Unfav Aspects',
            'fav_unfav_planets_table': fav_unfav_planets,
            'fav_unfav_cusps_table': fav_unfav_cusps,
            'calculation': 'Benefic planets Jupiter/Venus/Moon/Mercury aspects = Fav, Malefic Saturn/Mars/Sun/Rahu/Ketu = Unfav. Vedic aspects: Mars 4/7/8, Jupiter 5/7/9, Saturn 3/7/10'
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

def calculate_kp_balwan_karyesh(jd, panchang, lat, lon, kp_data, significator_data):
    """
    Page 13: K.P. Balwan Karyesh by planets and cusps
    Balwan = Strongest significator
    In KP, strongest significator is determined by:
    1. Planet in own star and own sub
    2. Planet in own star
    3. Occupant in order of sub lord strength
    4. Owner, etc
    Simplified: Rank significators by level and by natural strength
    """
    try:
        planet_details = kp_data.get('planet_details', [])
        cusp_details = kp_data.get('cusp_details', [])
        sig_planets_table = significator_data.get('significator_planets_table', []) if significator_data else []
        sig_cusps_table = significator_data.get('significator_cusps_table', []) if significator_data else []
        
        # For each house, find Balwan (strongest) planet significator
        balwan_by_planets = []
        
        for house_sig in sig_planets_table:
            house = house_sig['house']
            significators = house_sig['significators']
            
            # Rank significators by strength
            # Level 1 (Occupant) strongest, then Level 2 (Owner), Level 3 (Star of Occupant), Level 4 (Star of Owner)
            # Within same level, check if planet is in own star/sub - stronger
            # Also natural strength: Rahu/Ketu strong, etc
            
            ranked = []
            for sig in significators:
                planet_name = sig['planet']
                level = sig['level']
                
                # Find planet details
                p_detail = next((p for p in planet_details if p['planet'] == planet_name), None)
                
                strength_score = 0
                
                # Level weight (lower level = stronger, so invert)
                strength_score += (5 - level) * 100
                
                # If planet is in own star, +50
                if p_detail and p_detail['star_lord'] == planet_name:
                    strength_score += 50
                
                # If in own sub, +30
                if p_detail and p_detail['sub_lord'] == planet_name:
                    strength_score += 30
                
                # If planet is occupant of this house, strong
                if sig['type'] == 'Occupant':
                    strength_score += 20
                
                # Natural benefic/malefic weight - Rahu/Ketu considered strong for material houses
                if planet_name in ['Rahu','Ketu']:
                    strength_score += 10
                
                # If planet is in own house (rashi lord same as rashi)
                if p_detail and p_detail['rashi_lord'] == planet_name:
                    strength_score += 15
                
                ranked.append({
                    'planet': planet_name,
                    'level': level,
                    'reason': sig['reason'],
                    'type': sig['type'],
                    'strength_score': strength_score,
                    'details': p_detail
                })
            
            # Sort by strength descending
            ranked.sort(key=lambda x: x['strength_score'], reverse=True)
            
            balwan_by_planets.append({
                'house': house,
                'all_significators_ranked': ranked,
                'balwan_planet': ranked[0] if ranked else None,
                'second_balwan': ranked[1] if len(ranked) > 1 else None,
                'total_significators': len(ranked)
            })
        
        # For each planet, find Balwan cusp (strongest house it signifies)
        balwan_by_cusps = []
        
        for planet_sig in sig_cusps_table:
            planet_name = planet_sig['planet']
            houses_list = planet_sig['signifies_houses']
            
            # Rank houses by strength for this planet
            # Houses: Kendra, Trikona strong, Upachaya, etc
            # Also consider if planet is owner of house, occupant, etc
            
            ranked_houses = []
            for sig in houses_list:
                house = sig['house']
                level = sig['level']
                
                strength = (5 - level) * 100
                
                # If house is Kendra (1,4,7,10) or Trikona (1,5,9) strong
                if house in [1,5,9]:
                    strength += 30
                elif house in [4,7,10]:
                    strength += 20
                elif house in [2,3,11]:
                    strength += 10
                elif house in [6,8,12]:
                    strength -= 10  # Dusthana weak unless planet is malefic and good for upachaya
                
                ranked_houses.append({
                    'house': house,
                    'level': level,
                    'reason': sig['reason'],
                    'strength_score': strength
                })
            
            ranked_houses.sort(key=lambda x: x['strength_score'], reverse=True)
            
            balwan_by_cusps.append({
                'planet': planet_name,
                'all_houses_ranked': ranked_houses,
                'balwan_house': ranked_houses[0] if ranked_houses else None,
                'second_balwan_house': ranked_houses[1] if len(ranked_houses) > 1 else None,
                'total_houses': len(ranked_houses)
            })
        
        return {
            'title': 'K.P. Balwan Karyesh',
            'balwan_karyesh_by_planets_table': balwan_by_planets,
            'balwan_karyesh_by_cusps_table': balwan_by_cusps,
            'calculation': 'Balwan = Strongest significator. Ranked by: Level (Occupant > Owner > Star of Occupant > Star of Owner) + Own star/sub bonus + Own house + Natural strength. Highest score = Balwan Karyesh'
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}



def kundali_full_details_5levels(jd, moon_sid_deg, birth_jd=None, panchang=None, lat=18.52, lon=73.85):
    """TAB 98: KUNDALI - Corrected Calculations - No Defaults - Input Tabs Below Chart Types Above Kundali Tile"""
