        yoga_names = ["Vishkambha","Priti","Ayushman","Saubhagya","Shobhana","Atiganda","Sukarma","Dhriti","Shoola","Ganda","Vriddhi","Dhruva","Vyaghata","Harshana","Vajra","Siddhi","Vyatipata","Variyana","Parigha","Shiva","Siddha","Sadhya","Shubha","Shukla","Brahma","Indra","Vaidhriti"]
        karan_names = ["Bava","Balava","Kaulava","Taitila","Gara","Vanija","Vishti (Bhadra)","Shakuni","Chatushpada","Naga","Kimstughna"]
        
        # Correct calculations
        moon_nak_idx = int(moon_sid //13.333333333333334) %27
        moon_rasi_idx = int(moon_sid //30) %12
        sun_rasi_idx = int(sun_sid //30) %12
        vara_idx = int((jd_use + 1.5) %7)  # 0=Sunday
        nak_pada = int((moon_sid %13.333333333333334) //3.3333333333333335) +1
        # 108 akshar map - Correct as per classical
        akshar_map_108 = {
            0: ["Chu","Che","Cho","La"], 1: ["Li","Lu","Le","Lo"], 2: ["A","I","U","E"], 3: ["O","Va","Vi","Vu"], 4: ["Ve","Vo","Ka","Ki"],
            5: ["Ku","Gha","Na","Chha"], 6: ["Ke","Ko","Ha","Hi"], 7: ["Hu","He","Ho","Da"], 8: ["Di","Du","De","Do"], 9: ["Ma","Mi","Mu","Me"],
            10: ["Mo","Ta","Ti","Tu"], 11: ["Te","To","Pa","Pi"], 12: ["Pu","Sha","Na","Tha"], 13: ["Pe","Po","Ra","Ri"], 14: ["Ru","Re","Ro","Ta"],
            15: ["Ti","Tu","Te","To"], 16: ["Na","Ni","Nu","Ne"], 17: ["No","Ya","Yi","Yu"], 18: ["Ye","Yo","Bha","Bhi"], 19: ["Bhu","Dha","Pha","Dha"],
            20: ["Bhe","Bho","Ja","Ji"], 21: ["Ju","Je","Jo","Ga"], 22: ["Gi","Gu","Ge","Go"], 23: ["Sa","Si","Su","Se"], 24: ["So","Da","Di","Du"],
            25: ["Tha","Jha","Da","De"], 26: ["Do","Cha","Chi","Chu"]
        }
        nak_akshar = akshar_map_108[moon_nak_idx][nak_pada-1] if moon_nak_idx in akshar_map_108 and nak_pada-1 <4 else ""
        
        # Tithi - Correct: (Moon - Sun)/12 deg
        tithi_deg = (moon_trop - sun_trop) %360
        tithi_num = int(tithi_deg //12) +1  # 1-30
        if tithi_num <=15:
            paksha = "Shukla Paksha"
            tithi_name = tithi_names_shukla[tithi_num-1]
        else:
            paksha = "Krishna Paksha"
            tithi_name = tithi_names_krishna[tithi_num-16]
        
        # Yoga - Correct: (Sun_trop + Moon_trop)/13.333
        yoga_deg = (sun_trop + moon_trop) %360
        yoga_idx = int(yoga_deg //13.333333333333334) %27
        yoga_name = yoga_names[yoga_idx]
        
        # Karana - Correct: Tithi/2
        # 60 karanas in month, 4 fixed, 7 repeating
        karana_num = int(tithi_deg //6)  # 0-59
        if karana_num ==0:
            karan_name = "Kimstughna"
        elif karana_num >=57:
            # Last 3 are fixed: Shakuni, Chatushpada, Naga
            fixed = ["Shakuni","Chatushpada","Naga"]
            karan_name = fixed[karana_num-57]
        else:
            # Repeating 7
            rep = ["Bava","Balava","Kaulava","Taitila","Gara","Vanija","Vishti (Bhadra)"]
            karan_name = rep[(karana_num-1) %7]
        
        # Sunrise/Sunset - Correct with lat/lon and equation
        # Declination from sun_sid (approx)
        decl = 23.44 * math.sin(math.radians(sun_sid))
        lat_rad = math.radians(lat)
        decl_rad = math.radians(decl)
        cos_ha = -math.tan(lat_rad) * math.tan(decl_rad)
        cos_ha = max(-1, min(1, cos_ha))
        ha_deg = math.degrees(math.acos(cos_ha))
        ha_hours = ha_deg /15.0
        # LMT sunrise/sunset
        sunrise_lmt = 12 - ha_hours
        sunset_lmt = 12 + ha_hours
