# ============================================================================
# विविध ग्रह बल - VIVIDH GRAHA BALA - Planetary Strengths - ADDED AS REQUESTED
# ============================================================================
# 1. नैसर्गिक बल - Naisargik Bala - Natural Strength
# 2. काल बल - Kala Bala - Temporal Strength
# 3. दिग बल - Dig Bala - Directional Strength
# 4. चेष्टा बल - Chesta Bala - Motional Strength
# 5. नतोन्नत बल - Natonnata Bala - Meridian Strength
# 6. दृष्टी बल - Drishti Bala - Aspect Strength
# 7. भाव बल - Bhava Bala - House Strength
# ============================================================================

def calculate_naisargik_bala():
    """
    नैसर्गिक बल - Naisargik Bala - Natural Strength
    Based on natural brightness/size of planets - In Shastiamsas (0-60)
    Sun 60, Moon 51.43, Venus 42.85, Jupiter 34.28, Mercury 25.71, Mars 17.14, Saturn 8.57
    Source: Brihat Parashara Hora Shastra
    """
    # Shastiamsa values - Natural strength in order of brightness
    naisargik = {
        'sun': 60.0,
        'moon': 51.43,
        'venus': 42.85,
        'jupiter': 34.28,
        'mercury': 25.71,
        'mars': 17.14,
        'saturn': 8.57,
        'rahu': 0.0,  # Shadow planets have no naisargik bala
        'ketu': 0.0
    }
    return naisargik

def calculate_dig_bala(planet_sid, lagna_sid=None):
    """
    दिग बल - Dig Bala - Directional Strength - In Shastiamsas (0-60)
    Planets get maximum dig bala in certain houses:
    Mercury, Jupiter - East (Lagna - House 1) - 60 at 0° House 1
    Sun, Mars - South (10th House) - 60 at 0° House 10
    Saturn - West (7th House) - 60 at 0° House 7
    Moon, Venus - North (4th House) - 60 at 0° House 4
    Calculation: 60 - (distance from ideal point in degrees)/3
    """
    if lagna_sid is None:
        # Without lagna, return average
        return {
            'sun': 30.0, 'moon': 30.0, 'mercury': 30.0, 'venus': 30.0,
            'mars': 30.0, 'jupiter': 30.0, 'saturn': 30.0, 'rahu': 0.0, 'ketu': 0.0
        }
    
    # Ideal points for max dig bala (tropical - but we use sidereal with ayanamsa)
    # Mercury, Jupiter - Lagna (House 1) - 0° of House 1
    # Sun, Mars - 10th House - 0° of House 10
    # Saturn - 7th House - 0° of House 7
    # Moon, Venus - 4th House - 0° of House 4
    
    lagna_rashi = int(lagna_sid // 30)
    # House cusps (simplified - using rashi cusps)
    house_1_start = lagna_sid
    house_10_start = (lagna_sid + 270) % 360  # 10th house is 270° from Lagna
    house_7_start = (lagna_sid + 180) % 360   # 7th house is 180° from Lagna
    house_4_start = (lagna_sid + 90) % 360    # 4th house is 90° from Lagna
    
    dig_bala = {}
    
    for planet, sid in planet_sid.items():
        if planet.lower() in ['rahu', 'ketu']:
            dig_bala[planet.lower()] = 0.0
            continue
        
        # Find ideal point for this planet
        if planet.lower() in ['mercury', 'jupiter']:
            ideal = house_1_start
        elif planet.lower() in ['sun', 'mars']:
            ideal = house_10_start
        elif planet.lower() == 'saturn':
            ideal = house_7_start
        elif planet.lower() in ['moon', 'venus']:
            ideal = house_4_start
        else:
            ideal = house_1_start
        
        # Distance from ideal (shortest angular distance)
        diff = abs(sid - ideal)
        if diff > 180:
            diff = 360 - diff
        
        # Dig bala = 60 - diff/3, min 0, max 60
        bala = 60.0 - (diff / 3.0)
        if bala < 0:
            bala = 0.0
        if bala > 60:
            bala = 60.0
        
        dig_bala[planet.lower()] = bala
    
    return dig_bala

def calculate_kala_bala(jd, sun_sid, planet_sid):
    """
    काल बल - Kala Bala - Temporal Strength - In Shastiamsas (0-60)
    Includes:
    - Nathonnata Bala (Diurnal/Nocturnal)
    - Paksha Bala (Fortnight strength)
    - Tribhaga Bala (Day/Night divisions)
    - Varsha/Masa/Dina/Hora Bala (Year/Month/Day/Hour lords)
    Simplified version: Based on day/night and paksha
    """
    # Paksha Bala - Based on Moon's distance from Sun
    # Full Moon = 60, New Moon = 0
    moon_sid = planet_sid.get('moon', 0)
    sun_sid_val = sun_sid
    moon_sun_diff = (moon_sid - sun_sid_val) % 360
    paksha_bala = (moon_sun_diff / 180.0) * 60.0
    if paksha_bala > 60:
        paksha_bala = 120 - paksha_bala  # After full moon, decreases
    
    # Tribhaga Bala - Day/Night strength
    # This requires birth time - simplified: Day birth vs Night birth
    # For now, use Paksha as main
    
    kala_bala = {}
    for planet in ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'rahu', 'ketu']:
        if planet == 'moon':
            # Moon gets full Paksha Bala
            kala_bala[planet] = paksha_bala
        elif planet == 'sun':
            # Sun gets opposite of Moon's Paksha Bala
            kala_bala[planet] = 60.0 - paksha_bala
        else:
            # Other planets get average
            kala_bala[planet] = 30.0 + (paksha_bala - 30.0) * 0.5
    
    return kala_bala

def calculate_chesta_bala(planet_sid, sun_sid, planet_name):
    """
    चेष्टा बल - Chesta Bala - Motional Strength - In Shastiamsas (0-60)
    Based on planet's speed and retrograde motion
    Retrograde planets get higher chesta bala (except Sun, Moon)
    Formula: Based on distance from Sun (for outer planets) and retrograde
    """
    # Simplified: Check if retrograde (would need 2 days data)
    # For now, base on distance from Sun
    sun = sun_sid
    planet = planet_sid
    
    diff = (planet - sun) % 360
    if diff > 180:
        diff = 360 - diff
    
    # Chesta Bala = diff/3, max 60
    # Retrograde planets (approx when diff > 120 for outer planets) get more
    chesta = diff / 3.0
    if chesta > 60:
        chesta = 60.0
    
    # Retrograde check - if planet is retrograde, add 15
    # Simplified: Outer planets retrograde when Sun-Planet diff ~ 120-240
    # This is approximate - need actual speed calculation for exact
    is_retrograde = False
    if planet_name.lower() in ['mars', 'jupiter', 'saturn', 'mercury', 'venus']:
        # Check if in retrograde zone (approx)
        sun_planet_diff = (planet - sun) % 360
        if 120 < sun_planet_diff < 240:
            is_retrograde = True
            chesta += 15.0
            if chesta > 60:
                chesta = 60.0
    
    return chesta, is_retrograde

def calculate_drishti_bala(planet_sid, all_planets_sid):
    """
    दृष्टी बल - Drishti Bala - Aspect Strength - In Shastiamsas (0-60)
    Based on aspects from benefic and malefic planets
    Benefic aspect increases bala, malefic decreases
    """
    # Benefic planets: Jupiter (most benefic), Venus, Mercury, Moon
    # Malefic: Saturn (most malefic), Mars, Sun, Rahu, Ketu
    
    benefic = ['jupiter', 'venus', 'mercury', 'moon']
    malefic = ['saturn', 'mars', 'sun', 'rahu', 'ketu']
    
    drishti_bala = {}
    
    for planet, sid in all_planets_sid.items():
        if planet.lower() in ['rahu', 'ketu']:
            drishti_bala[planet.lower()] = 0.0
            continue
        
        bala = 30.0  # Base
        
        # Check aspects from all other planets
        for other_planet, other_sid in all_planets_sid.items():
            if other_planet == planet:
                continue
            
            diff = abs(sid - other_sid)
            if diff > 180:
                diff = 360 - diff
            
            # Aspect strength based on angle
            # 0° (conjunction), 60°, 90°, 120°, 180° are strong aspects
            # Simplified: If within 10° of aspect, give full strength
            aspect_angles = [0, 60, 90, 120, 180]
            aspect_strength = 0
            
            for asp in aspect_angles:
                if abs(diff - asp) < 10:
                    aspect_strength = 15.0 - abs(diff - asp)
                    break
            
            if aspect_strength > 0:
                if other_planet.lower() in benefic:
                    bala += aspect_strength
                elif other_planet.lower() in malefic:
                    bala -= aspect_strength * 0.8
        
        if bala < 0:
            bala = 0.0
        if bala > 60:
            bala = 60.0
        
        drishti_bala[planet.lower()] = bala
    
    return drishti_bala

def calculate_bhava_bala(planet_sid, lagna_sid, bhava_cusps=None):
    """
    भाव बल - Bhava Bala - House Strength - In Shastiamsas (0-60)
    Based on house placement - Planets in Kendra (1,4,7,10) get more strength
    Kendra (1,4,7,10): 60, Panaphara (2,5,8,11): 30, Apoklima (3,6,9,12): 15
    """
    if lagna_sid is None:
        return {p: 30.0 for p in ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'rahu', 'ketu']}
    
    lagna_rashi = int(lagna_sid // 30)
    bhava_bala = {}
    
    for planet, sid in planet_sid.items():
        rashi_num = int(sid // 30) + 1
        lagna_rashi_num = lagna_rashi + 1
        house = (rashi_num - lagna_rashi_num + 12) % 12 + 1
        
        # Kendra houses (1,4,7,10) - 60
        # Panaphara (2,5,8,11) - 30
        # Apoklima (3,6,9,12) - 15
        if house in [1, 4, 7, 10]:
            bala = 60.0
        elif house in [2, 5, 8, 11]:
            bala = 30.0
        else:
            bala = 15.0
        
        bhava_bala[planet.lower()] = bala
    
    return bhava_bala

def calculate_all_graha_bala(jd, lat, lon, full_panchang_data):
    """
    विविध ग्रह बल - All Planetary Strengths - Complete Calculation
    Returns all 7 types of bala for all planets
    """
    sun_sid = full_panchang_data['sun']['sid']
    moon_sid = full_panchang_data['moon']['sid']
    lagna_sid = full_panchang_data['lagna']['sid']
    
    # Collect all planet sidereal longitudes
    all_planets_sid = {
        'sun': sun_sid,
        'moon': moon_sid,
        'rahu': full_panchang_data['rahu'],
        'ketu': full_panchang_data['ketu']
    }
    
    for p in ['mercury', 'venus', 'mars', 'jupiter', 'saturn']:
        if p in full_panchang_data['planets']:
            all_planets_sid[p] = full_panchang_data['planets'][p]['sid']
    
    # Calculate all balas
    naisargik = calculate_naisargik_bala()
    dig = calculate_dig_bala(all_planets_sid, lagna_sid)
    kala = calculate_kala_bala(jd, sun_sid, all_planets_sid)
    drishti = calculate_drishti_bala(all_planets_sid, all_planets_sid)
    bhava = calculate_bhava_bala(all_planets_sid, lagna_sid)
    
    # Chesta Bala for each planet
    chesta = {}
    retrograde = {}
    for planet, sid in all_planets_sid.items():
        if planet in ['sun', 'moon', 'rahu', 'ketu']:
            chesta[planet] = 0.0 if planet in ['rahu', 'ketu'] else 30.0
            retrograde[planet] = False
        else:
            ch, retro = calculate_chesta_bala(sid, sun_sid, planet)
            chesta[planet] = ch
            retrograde[planet] = retro
    
    # Natonnata Bala - Simplified as part of Kala Bala - Diurnal strength
    natonnata = {}
    for planet in all_planets_sid.keys():
        # Day birth vs Night birth - Simplified
        # For now, use Kala Bala as base
        natonnata[planet] = kala.get(planet, 30.0) * 0.8
    
    # Total Bala
    total_bala = {}
    for planet in all_planets_sid.keys():
        total = (
            naisargik.get(planet, 0) +
            dig.get(planet, 0) +
            kala.get(planet, 0) +
            chesta.get(planet, 0) +
            natonnata.get(planet, 0) +
            drishti.get(planet, 0) +
            bhava.get(planet, 0)
        ) / 7.0
        total_bala[planet] = total
    
    return {
        'naisargik_bala': naisargik,
        'dig_bala': dig,
        'kala_bala': kala,
        'chesta_bala': chesta,
        'natonnata_bala': natonnata,
        'drishti_bala': drishti,
        'bhava_bala': bhava,
        'total_bala': total_bala,
        'retrograde': retrograde,
        'all_planets_sid': all_planets_sid
    }

