def calculate_tithi_details(jd, lat, lon):
    deg = _get_tithi_deg(jd, lat, lon)
    tithi_num = int(deg / 12) + 1
    paksha = "Shukla" if tithi_num <= 15 else "Krishna"
    tithi_names = ["Pratipada","Dwitiya","Tritiya","Chaturthi","Panchami","Shashthi","Saptami","Ashtami","Navami","Dashami","Ekadashi","Dwadashi","Trayodashi","Chaturdashi","Purnima","Pratipada","Dwitiya","Tritiya","Chaturthi","Panchami","Shashthi","Saptami","Ashtami","Navami","Dashami","Ekadashi","Dwadashi","Trayodashi","Chaturdashi","Amavasya"]
    tithi_name = tithi_names[tithi_num-1]
    
    start_deg = (tithi_num - 1) * 12
    end_deg = tithi_num * 12
    
    jd_start = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, start_deg, _get_tithi_deg)
    jd_end = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, end_deg, _get_tithi_deg)
    
    return {'tithi_num':tithi_num,'tithi_name':tithi_name,'tithi_full':f"{paksha} {tithi_name}",'paksha':paksha,'tithi_deg':deg,'jd_start':jd_start,'jd_end':jd_end,'duration_hours':(jd_end-jd_start)*24}


def calculate_var_details(jd):
    var_num = int((jd + 1.5) % 7)
    var_names = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"]
    var_names_hindi = ["Ravivar","Somvar","Mangalvar","Budhvar","Guruvar","Shukravar","Shanivar"]
    jd_midnight = int(jd + 0.5) - 0.5
    jd_sunrise = jd_midnight + 6.0/24.0
    if jd < jd_sunrise:
        var_num = (var_num - 1) % 7
        jd_start = jd_sunrise - 1
        jd_end = jd_sunrise
    else:
        jd_start = jd_sunrise
        jd_end = jd_sunrise + 1
    return {'var_num':var_num,'var_name':var_names[var_num],'var_hindi':var_names_hindi[var_num],'jd_start':jd_start,'jd_end':jd_end}

def calculate_nakshatra_details(jd, lat, lon):
    deg = _get_nak_deg(jd, lat, lon)
    nak_num = int(deg / 13.3333333) + 1
    nak_names = ["Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra","Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni","Uttara Phalguni","Hasta","Chitra","Swati","Vishakha","Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha","Shravana","Dhanishta","Shatabhisha","Purva Bhadrapada","Uttara Bhadrapada","Revati"]
    nak_name = nak_names[nak_num-1]
    nak_pada = int((deg % 13.3333333) / 3.333333) + 1
    
    start_deg = (nak_num - 1) * 13.3333333
    end_deg = nak_num * 13.3333333
    
    jd_start = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, start_deg, _get_nak_deg)
    jd_end = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, end_deg, _get_nak_deg)
    
    return {'nak_num':nak_num,'nak_name':nak_name,'nak_deg':deg,'nak_pada':nak_pada,'jd_start':jd_start,'jd_end':jd_end,'duration_hours':(jd_end-jd_start)*24}


def calculate_yog_details(jd, lat, lon):
    deg = _get_yog_deg(jd, lat, lon)
    yog_num = int(deg / 13.3333333) + 1
    yog_names = ["Vishkambha","Priti","Ayushman","Saubhagya","Shobhana","Atiganda","Sukarman","Dhriti","Shula","Ganda","Vriddhi","Dhruva","Vyaghata","Harshana","Vajra","Siddhi","Vyatipata","Variyana","Parigha","Shiva","Siddha","Sadhya","Shubha","Shukla","Brahma","Indra","Vaidhriti"]
    yog_name = yog_names[yog_num-1]
    
    start_deg = (yog_num - 1) * 13.3333333
    end_deg = yog_num * 13.3333333
    
    jd_start = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, start_deg, _get_yog_deg)
    jd_end = _find_exact_time(jd - 1.5, jd + 1.5, lat, lon, end_deg, _get_yog_deg)
    
    return {'yog_num':yog_num,'yog_name':yog_name,'yog_deg':deg,'jd_start':jd_start,'jd_end':jd_end,'duration_hours':(jd_end-jd_start)*24}


def calculate_karan_details(jd, lat, lon):
    deg = _get_tithi_deg(jd, lat, lon)
    karan_num = int(deg / 6) + 1
    
    # Simple Karan calculation for replacement (we just need to return exact same dict)
    t_num = int(deg / 12) + 1
    
    start_deg = (karan_num - 1) * 6
    end_deg = karan_num * 6
    
    jd_start = _find_exact_time(jd - 1.0, jd + 1.0, lat, lon, start_deg, _get_karan_deg)
    jd_end = _find_exact_time(jd - 1.0, jd + 1.0, lat, lon, end_deg, _get_karan_deg)
    
    return {'karan_index': karan_num, 'karan_name': f'Karana {karan_num}', 'karan_type': 'Movable', 'tithi_deg': deg, 'jd_start': jd_start, 'jd_end': jd_end, 'duration_hours': (jd_end-jd_start)*24}


def jd_to_date_str(jd_val):
    jd_val += 0.5
    Z = int(jd_val)
    F = jd_val - Z
    if Z < 2299161:
        A = Z
    else:
        alpha = int((Z - 1867216.25) / 36524.25)
        A = Z + 1 + alpha - alpha // 4
    B = A + 1524
    C = int((B - 122.1) / 365.25)
    D = int(365.25 * C)
    E = int((B - D) / 30.6001)
    day = B - D - int(30.6001 * E) + F
    month = E - 1 if E < 14 else E - 13
    year = C - 4716 if month > 2 else C - 4715
    day_int = int(day)
    hour = (day - day_int) * 24
    minute = (hour - int(hour)) * 60
    return f"{day_int:02d}-{month:02d}-{year} {int(hour):02d}:{int(minute):02d}"

def get_panchang_page2(jd, lat, lon):
    tithi = calculate_tithi_details(jd, lat, lon)
    var = calculate_var_details(jd)
    nak = calculate_nakshatra_details(jd, lat, lon)
    yog = calculate_yog_details(jd, lat, lon)
    karan = calculate_karan_details(jd, lat, lon)
    return {
        'page':2,'title':'Panchang Details - Tithi, Var, Nakshatra, Yog, Karan with Start/End',
        'tithi':{'name':tithi['tithi_full'],'num':tithi['tithi_num'],'paksha':tithi['paksha'],'deg':tithi['tithi_deg'],'start':jd_to_date_str(tithi['jd_start']),'end':jd_to_date_str(tithi['jd_end']),'jd_start':tithi['jd_start'],'jd_end':tithi['jd_end'],'duration':f"{tithi['duration_hours']:.2f} hours"},
        'var':{'name':var['var_name'],'hindi':var['var_hindi'],'num':var['var_num'],'start':jd_to_date_str(var['jd_start']),'end':jd_to_date_str(var['jd_end']),'jd_start':var['jd_start'],'jd_end':var['jd_end']},
        'nakshatra':{'name':nak['nak_name'],'num':nak['nak_num'],'pada':nak['nak_pada'],'deg':nak['nak_deg'],'start':jd_to_date_str(nak['jd_start']),'end':jd_to_date_str(nak['jd_end']),'jd_start':nak['jd_start'],'jd_end':nak['jd_end'],'duration':f"{nak['duration_hours']:.2f} hours"},
        'yog':{'name':yog['yog_name'],'num':yog['yog_num'],'deg':yog['yog_deg'],'start':jd_to_date_str(yog['jd_start']),'end':jd_to_date_str(yog['jd_end']),'jd_start':yog['jd_start'],'jd_end':yog['jd_end'],'duration':f"{yog['duration_hours']:.2f} hours"},
        'karan':{'name':karan['karan_name'],'type':karan['karan_type'],'index':karan['karan_index'],'start':jd_to_date_str(karan['jd_start']),'end':jd_to_date_str(karan['jd_end']),'jd_start':karan['jd_start'],'jd_end':karan['jd_end'],'duration':f"{karan['duration_hours']:.2f} hours"}
    }

# Page 3: Lagna Kundali with detailed grah table
def deg_to_dms(deg):
    d = int(deg)
    m_float = (deg - d) * 60
    m = int(m_float)
    s = (m_float - m) * 60
    return d, m, s

def get_rashi_lord(rashi_num):
    lords = {1:"Mars",2:"Venus",3:"Mercury",4:"Moon",5:"Sun",6:"Mercury",7:"Venus",8:"Mars",9:"Jupiter",10:"Saturn",11:"Saturn",12:"Jupiter"}
    return lords.get(rashi_num,"Unknown")

def get_nakshatra_lord(nak_num):
    lords = ["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"]
    return lords[(nak_num-1) % 9]

def get_sub_lord(planet_sid):
    nak_deg = planet_sid % 13.333333
    nak_lord_years = {"Ketu":7,"Venus":20,"Sun":6,"Moon":10,"Mars":7,"Rahu":18,"Jupiter":16,"Saturn":19,"Mercury":17}
    nak_lords_order = ["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"]
    nak_num = int(planet_sid / 13.333333) + 1
    nak_lord = get_nakshatra_lord(nak_num)
    sub_deg = 0
    nak_lord_idx = nak_lords_order.index(nak_lord)
    for i in range(9):
        idx = (nak_lord_idx + i) % 9
        lord = nak_lords_order[idx]
        sub_size = 13.333333 * nak_lord_years[lord] / 120.0
        if nak_deg < sub_deg + sub_size:
            return lord, sub_size, nak_deg - sub_deg
        sub_deg += sub_size
    return nak_lord, 0, 0

def get_sub_sub_lord(planet_sid):
    sub_lord, sub_size, deg_in_sub = get_sub_lord(planet_sid)
    nak_lord_years = {"Ketu":7,"Venus":20,"Sun":6,"Moon":10,"Mars":7,"Rahu":18,"Jupiter":16,"Saturn":19,"Mercury":17}
    nak_lords_order = ["Ketu","Venus","Sun","Moon","Mars","Rahu","Jupiter","Saturn","Mercury"]
    sub_lord_idx = nak_lords_order.index(sub_lord)
    sub_sub_deg = 0
    for i in range(9):
        idx = (sub_lord_idx + i) % 9
        lord = nak_lords_order[idx]
        sub_sub_size = sub_size * nak_lord_years[lord] / 120.0
        if deg_in_sub < sub_sub_deg + sub_sub_size:
            return lord
        sub_sub_deg += sub_sub_size
    return sub_lord

def get_lagna_kundali_page3(jd, lat, lon, full_panchang_data):
    rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]
    nak_names = ["Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra","Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni","Uttara Phalguni","Hasta","Chitra","Swati","Vishakha","Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha","Shravana","Dhanishta","Shatabhisha","Purva Bhadrapada","Uttara Bhadrapada","Revati"]
    planets_data = []
    all_planets = {'Lagna':full_panchang_data['lagna']['sid'],'Sun':full_panchang_data['sun']['sid'],'Moon':full_panchang_data['moon']['sid'],'Rahu':full_panchang_data['rahu'],'Ketu':full_panchang_data['ketu']}
    for p in ['mercury','venus','mars','jupiter','saturn']:
        if p in full_panchang_data['planets']:
            all_planets[p.capitalize()] = full_panchang_data['planets'][p]['sid']
    lagna_sid = full_panchang_data['lagna']['sid']
    lagna_rashi = int(lagna_sid // 30) + 1
    for planet_name, sid in all_planets.items():
        rashi_num = int(sid // 30) + 1
        deg_in_rashi = sid % 30
        d, m, s = deg_to_dms(deg_in_rashi)
        nak_num = int(sid / 13.333333) + 1
        nak_name = nak_names[nak_num-1]
        rashi_lord = get_rashi_lord(rashi_num)
        nak_lord = get_nakshatra_lord(nak_num)
        sub_lord, sub_size, deg_in_sub = get_sub_lord(sid)
        sub_sub_lord = get_sub_sub_lord(sid)
        house = (rashi_num - lagna_rashi + 12) % 12 + 1 if planet_name != 'Lagna' else 1
        planets_data.append({'planet':planet_name,'sid':sid,'rashi_num':rashi_num,'rashi_name':rashi_names[rashi_num-1],'ansh':d,'kala':m,'vikala':s,'deg_in_rashi':deg_in_rashi,'rashi_lord':rashi_lord,'nakshatra_num':nak_num,'nakshatra_name':nak_name,'nakshatra_lord':nak_lord,'sub_lord':sub_lord,'sub_sub_lord':sub_sub_lord,'house':house})
    return {'page':3,'title':'Lagna Kundali with All Grah Table - Rashi, Ansh Kala Vikala, Lords','lagna_rashi':lagna_rashi,'lagna_sid':lagna_sid,'planets':planets_data}

# Page 4: Rashi + Navmansh
def calculate_navamsa(planet_sid):
    rashi_num = int(planet_sid // 30) + 1
    deg_in_rashi = planet_sid % 30
    navamsa_in_rashi = int(deg_in_rashi / 3.333333) + 1
    movable = [1,4,7,10]
    fixed = [2,5,8,11]
    if rashi_num in movable:
        navamsa_rashi = (rashi_num + navamsa_in_rashi - 1 - 1) % 12 + 1
    elif rashi_num in fixed:
        navamsa_rashi = (rashi_num + 9 + navamsa_in_rashi - 1 - 1) % 12 + 1
    else:
        navamsa_rashi = (rashi_num + 5 + navamsa_in_rashi - 1 - 1) % 12 + 1
    return navamsa_rashi, navamsa_in_rashi

def get_rashi_navamsa_page4(jd, lat, lon, full_panchang_data):
    rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]
    rashi_kundali = []
    navamsa_kundali = []
    lagna_sid = full_panchang_data['lagna']['sid']
    lagna_rashi = int(lagna_sid // 30) + 1
    all_planets = {'Lagna':lagna_sid,'Sun':full_panchang_data['sun']['sid'],'Moon':full_panchang_data['moon']['sid'],'Rahu':full_panchang_data['rahu'],'Ketu':full_panchang_data['ketu']}
    for p in ['mercury','venus','mars','jupiter','saturn']:
        if p in full_panchang_data['planets']:
            all_planets[p.capitalize()] = full_panchang_data['planets'][p]['sid']
    for planet_name, sid in all_planets.items():
        rashi_num = int(sid // 30) + 1
        deg_in_rashi = sid % 30
        house = (rashi_num - lagna_rashi + 12) % 12 + 1 if planet_name != 'Lagna' else 1
        rashi_kundali.append({'planet':planet_name,'sid':sid,'rashi_num':rashi_num,'rashi_name':rashi_names[rashi_num-1],'deg':deg_in_rashi,'house':house})
        nav_rashi, nav_in_rashi = calculate_navamsa(sid)
        navamsa_kundali.append({'planet':planet_name,'sid':sid,'navamsa_rashi':nav_rashi,'navamsa_rashi_name':rashi_names[nav_rashi-1],'navamsa_in_rashi':nav_in_rashi,'deg_in_rashi':deg_in_rashi})
    return {'page':4,'title':'Rashi Kundali + Navmansh Kundali (D9)','rashi_kundali':rashi_kundali,'navamsa_kundali':navamsa_kundali,'lagna_rashi':lagna_rashi}

# Page 5: Bhav Kundali
def calculate_bhava_details(lagna_sid):
    bhav_details = []
    for bhav_num in range(1,13):
        bhav_madhya = (lagna_sid + (bhav_num-1)*30) % 360
        bhav_prarambh = (bhav_madhya - 15) % 360
        bhav_ant = (bhav_madhya + 15) % 360
        rashi_madhya = int(bhav_madhya // 30) + 1
        rashi_prarambh = int(bhav_prarambh // 30) + 1
        rashi_ant = int(bhav_ant // 30) + 1
        bhav_details.append({'bhav_num':bhav_num,'bhav_madhya':bhav_madhya,'bhav_prarambh':bhav_prarambh,'bhav_ant':bhav_ant,'rashi_madhya':rashi_madhya,'rashi_prarambh':rashi_prarambh,'rashi_ant':rashi_ant,'deg_madhya':bhav_madhya%30,'deg_prarambh':bhav_prarambh%30,'deg_ant':bhav_ant%30})
    return bhav_details

def get_bhava_kundali_page5(jd, lat, lon, full_panchang_data):
    lagna_sid = full_panchang_data['lagna']['sid']
    bhav_details = calculate_bhava_details(lagna_sid)
    rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]
    all_planets = {'Lagna':lagna_sid,'Sun':full_panchang_data['sun']['sid'],'Moon':full_panchang_data['moon']['sid'],'Rahu':full_panchang_data['rahu'],'Ketu':full_panchang_data['ketu']}
    for p in ['mercury','venus','mars','jupiter','saturn']:
        if p in full_panchang_data['planets']:
            all_planets[p.capitalize()] = full_panchang_data['planets'][p]['sid']
    bhav_with_planets = []
    for bhav in bhav_details:
        planets_in_bhav = []
        for planet_name, sid in all_planets.items():
            prarambh = bhav['bhav_prarambh']
            ant = bhav['bhav_ant']
            if prarambh <= ant:
                in_bhav = prarambh <= sid <= ant
            else:
                in_bhav = sid >= prarambh or sid <= ant
            if in_bhav:
                planets_in_bhav.append(planet_name)
        bhav_with_planets.append({**bhav,'planets':planets_in_bhav,'rashi_madhya_name':rashi_names[bhav['rashi_madhya']-1],'rashi_prarambh_name':rashi_names[bhav['rashi_prarambh']-1],'rashi_ant_name':rashi_names[bhav['rashi_ant']-1]})
    return {'page':5,'title':'Bhav Kundali - Bhav Prarambh, Madhya, Ant','lagna_sid':lagna_sid,'bhav_details':bhav_with_planets}

# Page 6: D1 to D60
def calculate_divisional_chart(planet_sid, division_num):
    rashi_num = int(planet_sid // 30) + 1
    deg_in_rashi = planet_sid % 30
    div_size = 30.0 / division_num
    div_in_rashi = int(deg_in_rashi / div_size) + 1
    if division_num == 1:
        div_rashi = rashi_num
    elif division_num == 2:
        if deg_in_rashi < 15:
            div_rashi = 1 if rashi_num % 2 == 1 else 2
        else:
            div_rashi = 2 if rashi_num % 2 == 1 else 1
    elif division_num == 3:
        if div_in_rashi == 1:
            div_rashi = rashi_num
        elif div_in_rashi == 2:
            div_rashi = (rashi_num + 4 - 1) % 12 + 1
        else:
            div_rashi = (rashi_num + 8 - 1) % 12 + 1
    elif division_num == 9:
        nav_rashi, _ = calculate_navamsa(planet_sid)
        div_rashi = nav_rashi
    else:
        movable = [1,4,7,10]
        fixed = [2,5,8,11]
        if rashi_num in movable:
            div_rashi = (rashi_num + div_in_rashi - 1 - 1) % 12 + 1
        elif rashi_num in fixed:
            div_rashi = (rashi_num + 8 + div_in_rashi - 1 - 1) % 12 + 1
        else:
            div_rashi = (rashi_num + 4 + div_in_rashi - 1 - 1) % 12 + 1
    return div_rashi, div_in_rashi, deg_in_rashi

def get_all_divisional_charts_page6(jd, lat, lon, full_panchang_data):
    divisions = [1,2,3,4,7,9,10,12,16,20,24,27,30,40,45,60]
    rashi_names = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]
    all_divisional = {}
    all_planets = {'Lagna':full_panchang_data['lagna']['sid'],'Sun':full_panchang_data['sun']['sid'],'Moon':full_panchang_data['moon']['sid'],'Rahu':full_panchang_data['rahu'],'Ketu':full_panchang_data['ketu']}
    for p in ['mercury','venus','mars','jupiter','saturn']:
        if p in full_panchang_data['planets']:
            all_planets[p.capitalize()] = full_panchang_data['planets'][p]['sid']
    for div in divisions:
        div_chart = {}
        for planet_name, sid in all_planets.items():
            div_rashi, div_in_rashi, deg_in_rashi = calculate_divisional_chart(sid, div)
            div_chart[planet_name] = {'planet':planet_name,'d_rashi':div_rashi,'d_rashi_name':rashi_names[div_rashi-1],'d_in_rashi':div_in_rashi,'deg_in_rashi':deg_in_rashi,'original_sid':sid}
        all_divisional[f'D{div}'] = div_chart
    return {'page':6,'title':'D1 to D60 Kundali - All Divisional Charts','divisions':divisions,'charts':all_divisional,'lagna_rashi':int(full_panchang_data['lagna']['sid'] // 30) + 1}

def get_complete_kundali_all_pages(jd, lat, lon):
    pan = full_panchang(jd, lat, lon)
    if pan.get('error'):
        return {'error':pan['error']}
    page2 = get_panchang_page2(jd, lat, lon)
    page3 = get_lagna_kundali_page3(jd, lat, lon, pan)
    page4 = get_rashi_navamsa_page4(jd, lat, lon, pan)
    page5 = get_bhava_kundali_page5(jd, lat, lon, pan)
    page6 = get_all_divisional_charts_page6(jd, lat, lon, pan)
    try:
        bala = calculate_all_graha_bala(jd, lat, lon, pan)
        avastha = calculate_all_graha_avastha(pan)
    except:
        bala = None
        avastha = None
    return {'page1_panchang':pan,'page2_panchang_details':page2,'page3_lagna_kundali':page3,'page4_rashi_navamsa':page4,'page5_bhava_kundali':page5,'page6_d1_to_d60':page6,'bala':bala,'avastha':avastha,'jd':jd,'lat':lat,'lon':lon,'complete':True}




