# TAB 99: DAILY POWER CHART V3 PERFECT - ALL LAWS AND CALCULATIONS - FINAL
# ============================================================================
# Perfect Formula V3 - 10 Laws with New User Slabs - Final Version
# Bhinna: 0-2=-0.5, 3=0, 4-5=+0.5, 6-7=+1.0
# Sarva: Below 23=0.00, 24-30=0.50, 31-40=0.75, 41-49=1.00
# No hardcoded dates, places, times - Fully generic - Any person
# Includes: Shadbala, Avastha, Bhinna, Sarva New Slabs, Vedha, Combust, Yuddha, Tara, Vakri
# Formula: Transit Corrected = Base + Avastha + Bhinna + Combust + Yuddha + Vakri
#          Daily Planet = (Birth*0.4 + Transit Corr*0.6) + Vedha + Tara
#          Daily House = Lord*0.4 + Occ Avg*0.3 + 1.35 + Sarva Corr + Tara
# ============================================================================

def calculate_daily_power_v3_perfect(jd_birth, pan_birth, lat, lon, jd_today=None):
    try:
        import datetime
        if jd_today is None:
            now = datetime.datetime.now()
            jd_today = to_jd(now.year, now.month, now.day, 19, 0, 0, lat, lon)
        pan_today = full_panchang(jd_today, lat, lon)
        try:
            bala_birth = calculate_all_graha_bala(jd_birth, lat, lon, pan_birth)
            bala_today = calculate_all_graha_bala(jd_today, lat, lon, pan_today)
        except:
            bala_birth = None
            bala_today = None
        def to_rupas(bala_dict):
            if not bala_dict:
                return {}
            rupas = {}
            for p in bala_dict.get('total_bala', {}):
                total = (
                    bala_dict.get('naisargik_bala', {}).get(p,0) +
                    bala_dict.get('dig_bala', {}).get(p,0) +
                    bala_dict.get('kala_bala', {}).get(p,0) +
                    bala_dict.get('chesta_bala', {}).get(p,0) +
                    bala_dict.get('drishti_bala', {}).get(p,0) +
                    bala_dict.get('bhava_bala', {}).get(p,0)
                )
                rupas[p] = total/60.0 if total>0 else 2.5
            return rupas
        birth_rupas = to_rupas(bala_birth)
        today_rupas = to_rupas(bala_today)
        avas_map = {
            'Deepta': 1.0, 'Swastha': 0.75, 'Mudita': 0.5, 'Santa': 0.25, 'Shanta': 0.25,
            'Sakta': 0.0, 'Kshudhita': -0.5, 'Kshobhita': -0.5, 'Deena': -0.5,
            'Vikala': -0.75, 'Mrita': -1.5, 'Khala': -1.0, 'Krodhi': -1.0, 'Vriddha': -0.75,
            'Bala': 0.0, 'Kumara': 0.0, 'Yuva': 0.0, 'Yuvana': 0.0, 'Jagrat': 0.0, 'Swapna': 0.0, 'Sushupta': 0.0
        }
        try:
            avas_today = avasthas_5levels(jd_today, pan_today['moon']['sid'], jd_today, pan_today, lat, lon)
            avas_dict = avas_today.get('avasthas', {})
        except:
            avas_dict = {}
        try:
            asht_birth = ashtakavarga_5levels(jd_birth, pan_birth['moon']['sid'], jd_birth, pan_birth, lat, lon)
            sarva_bindus = asht_birth.get('ashtakavarga', {}).get('Sarva', {}).get('bindus', [0]*12)
            bhinna_data = asht_birth.get('ashtakavarga', {})
        except:
            sarva_bindus = [0]*12
            bhinna_data = {}
        janma_nak = int(pan_birth['moon']['sid'] // 13.333333) % 27
        today_nak = int(pan_today['moon']['sid'] // 13.333333) % 27
        tara = (today_nak - janma_nak) % 27 + 1
        tara_type = tara % 9
        tara_map = {
            1: ("Janma", -0.25, -0.10),
            2: ("Sampat", 0.50, 0.25),
            3: ("Vipat", -0.75, -0.25),
            4: ("Kshema", 0.50, 0.25),
            5: ("Pratyari", -0.50, -0.15),
            6: ("Sadhaka", 0.75, 0.30),
            7: ("Vadha", -1.00, -0.50),
            8: ("Mitra", 0.50, 0.20),
            0: ("Ati Mitra", 0.75, 0.30),
        }
        tara_name, tara_moon, tara_all = tara_map.get(tara_type, ("Ati Mitra", 0.75, 0.30))
        sun_sid_today = pan_today['sun']['sid']
        combust_corr = {}
        orbs = {'mercury':14,'venus':10,'mars':17,'jupiter':11,'saturn':15}
        for pl in ['mercury','venus','mars','jupiter','saturn']:
            if pl in pan_today.get('planets', {}):
                pl_sid = pan_today['planets'][pl]['sid']
                diff = abs((pl_sid - sun_sid_today + 360) % 360)
                if diff > 180:
                    diff = 360 - diff
                orb = orbs[pl]
                if diff < 3:
                    corr = -1.5
                elif diff < orb:
                    corr = -1.0
                else:
                    corr = 0.0
                combust_corr[pl] = {'diff': diff, 'corr': corr}
        yuddha_corr = {}
        planets_today_sids = {}
        planets_today_sids['Sun'] = pan_today['sun']['sid']
        planets_today_sids['Moon'] = pan_today['moon']['sid']
        for p in ['mercury','venus','mars','jupiter','saturn']:
            if p in pan_today.get('planets', {}):
                planets_today_sids[p.capitalize()] = pan_today['planets'][p]['sid']
        for pl in planets_today_sids:
            yuddha_corr[pl.lower()] = 0.0
        planets_list = list(planets_today_sids.keys())
        for i in range(len(planets_list)):
            for j in range(i+1, len(planets_list)):
                pl1 = planets_list[i]
                pl2 = planets_list[j]
                if pl1 in ['Sun','Moon'] or pl2 in ['Sun','Moon']:
                    continue
                diff = abs((planets_today_sids[pl1] - planets_today_sids[pl2] + 360) % 360)
                if diff > 180:
                    diff = 360 - diff
                if diff < 1.0:
                    naisargik = {'Sun':60,'Moon':51.43,'Venus':42.85,'Jupiter':34.28,'Mercury':25.71,'Mars':17.14,'Saturn':8.57}
                    nb1 = naisargik.get(pl1, 0)
                    nb2 = naisargik.get(pl2, 0)
                    if nb1 > nb2:
                        yuddha_corr[pl1.lower()] = 0.5
                        yuddha_corr[pl2.lower()] = -0.75
                    else:
                        yuddha_corr[pl1.lower()] = -0.75
                        yuddha_corr[pl2.lower()] = 0.5
        vakri_corr = {}
        for pl in ['mercury','venus','mars','jupiter','saturn']:
            if pl in pan_today.get('planets', {}):
                retro = pan_today['planets'][pl].get('retro', False)
                if retro:
                    sid = pan_today['planets'][pl]['sid']
                    rashi = int(sid//30)+1
                    own_rashi = {'mercury':[3,6],'venus':[2,7],'mars':[1,8],'jupiter':[9,12],'saturn':[10,11]}
                    is_own = rashi in own_rashi.get(pl, [])
                    exalt_rashi = {'mercury':6,'venus':12,'mars':10,'jupiter':4,'saturn':7}
                    is_exalt = rashi == exalt_rashi.get(pl, 0)
                    if is_own or is_exalt:
                        vakri_corr[pl] = 0.75
                    else:
                        vakri_corr[pl] = 0.5
                else:
                    vakri_corr[pl] = 0.0
        lagna_birth = pan_birth['lagna']['sid']
        daily_planets = []
        planet_keys = ['sun','moon','mercury','venus','mars','jupiter','saturn','rahu','ketu']
        for planet in planet_keys:
            birth = birth_rupas.get(planet, 2.5)
            today_base = today_rupas.get(planet, 2.5)
            avas_key_map = {'sun':'Sun','moon':'Moon','mercury':'Mercury','venus':'Venus','mars':'Mars','jupiter':'Jupiter','saturn':'Saturn','rahu':'Rahu','ketu':'Ketu'}
            avas_key = avas_key_map.get(planet, planet.capitalize())
            avas_info = avas_dict.get(avas_key, {})
            deeptadi = avas_info.get('deeptadi', 'Sakta')
            avas_corr = avas_map.get(deeptadi, 0.0)
            if planet == 'sun':
                today_sid = pan_today['sun']['sid']
            elif planet == 'moon':
                today_sid = pan_today['moon']['sid']
            elif planet == 'rahu':
                today_sid = pan_today['rahu']
            elif planet == 'ketu':
                today_sid = (pan_today['rahu'] + 180) % 360
            else:
                if planet in pan_today.get('planets', {}):
                    today_sid = pan_today['planets'][planet]['sid']
                else:
                    today_sid = 0
            today_house = int((today_sid - lagna_birth) % 360 // 30) + 1 if lagna_birth else 1
            bhinna_bindus = [0]*12
            for key in bhinna_data:
                if key.lower() == planet.lower():
                    bhinna_bindus = bhinna_data[key].get('bindus', [0]*12)
                    break
            bhinna_val = bhinna_bindus[today_house-1] if today_house>=1 and today_house<=12 and len(bhinna_bindus)>=today_house else 0
            if planet in ['rahu','ketu']:
                bhinna_corr = 0.0
                bhinna_val = 0
            else:
                if bhinna_val <=2:
                    bhinna_corr = -0.5
                elif bhinna_val ==3:
                    bhinna_corr = 0.0
                elif bhinna_val <=5:
                    bhinna_corr = 0.5
                else:
                    bhinna_corr = 1.0
            combust = combust_corr.get(planet, {}).get('corr', 0.0) if planet in combust_corr else 0.0
            yuddha = yuddha_corr.get(planet, 0.0)
            vakri = vakri_corr.get(planet, 0.0)
            transit_corr = today_base + avas_corr + bhinna_corr + combust + yuddha + vakri
            vedha_corr = 0.0
            daily_power = (birth * 0.4 + transit_corr * 0.6) + vedha_corr + tara_all
            if planet == 'moon':
                daily_power += tara_moon
            thresholds = {'sun':6.5,'moon':6.0,'mars':5.0,'mercury':7.0,'jupiter':6.5,'venus':5.5,'saturn':5.0,'rahu':5.0,'ketu':5.0}
            thr = thresholds.get(planet, 5.0)
            if daily_power >= thr + 1.0:
                rating = "Ati Balwan"
            elif daily_power >= thr:
                rating = "Balwan"
            elif daily_power >= thr -1.0:
                rating = "Madhyam"
            elif daily_power >= thr -2.0:
                rating = "Nirbal"
            else:
                rating = "Ati Nirbal"
            daily_planets.append({
                'planet': planet.capitalize(),
                'birth_rupa': round(birth,2),
                'today_base': round(today_base,2),
                'today_house': today_house,
                'avastha': deeptadi,
                'avas_corr': avas_corr,
                'bhinna_bindu': bhinna_val,
                'bhinna_corr': bhinna_corr,
                'combust_corr': combust,
                'yuddha_corr': yuddha,
                'vakri_corr': vakri,
                'transit_corr': round(transit_corr,2),
                'vedha_corr': vedha_corr,
                'tara_all': tara_all,
                'tara_moon_extra': tara_moon if planet=='moon' else 0,
                'daily_power': round(daily_power,2),
                'rating': rating
            })
        def sarva_corr_from_bindu(bindu):
            if bindu < 23:
                return 0.00
            elif bindu <=30:
                return 0.50
            elif bindu <=40:
                return 0.75
            else:
                return 1.00
        rashi_lords = {1:"Mars",2:"Venus",3:"Mercury",4:"Moon",5:"Sun",6:"Mercury",7:"Venus",8:"Mars",9:"Jupiter",10:"Saturn",11:"Saturn",12:"Jupiter"}
        lagna_rashi = int(lagna_birth //30) +1 if lagna_birth else 1
        daily_houses = []
        daily_power_dict = {p['planet'].lower(): p['daily_power'] for p in daily_planets}
        birth_planets_sids = {}
        birth_planets_sids['Sun'] = pan_birth['sun']['sid']
        birth_planets_sids['Moon'] = pan_birth['moon']['sid']
        birth_planets_sids['Rahu'] = pan_birth['rahu']
        birth_planets_sids['Ketu'] = (pan_birth['rahu']+180)%360
        for p in ['mercury','venus','mars','jupiter','saturn']:
            if p in pan_birth.get('planets', {}):
                birth_planets_sids[p.capitalize()] = pan_birth['planets'][p]['sid']
        for house in range(1,13):
            rashi_num = (lagna_rashi + house -1 -1) %12 +1
            lord = rashi_lords[rashi_num]
            lord_power = daily_power_dict.get(lord.lower(), 4.5)
            occupants = []
            for pl_name, sid in birth_planets_sids.items():
                h = int((sid - lagna_birth) %360 //30)+1
                if h == house:
                    occupants.append(pl_name)
            if occupants:
                occ_avg = sum(daily_power_dict.get(pl.lower(), 4.5) for pl in occupants) / len(occupants)
            else:
                occ_avg = 4.5
            sarva_bindu = sarva_bindus[house-1] if house<=len(sarva_bindus) else 0
            sarva_corr = sarva_corr_from_bindu(sarva_bindu)
            house_power = (lord_power *0.40) + (occ_avg *0.30) + 1.35 + sarva_corr + tara_all
            if house_power >= 6.0:
                h_rating = "Ati Balwan"
            elif house_power >=5.0:
                h_rating = "Balwan"
            elif house_power >=4.0:
                h_rating = "Madhyam"
            elif house_power >=3.0:
                h_rating = "Nirbal"
            else:
                h_rating = "Ati Nirbal"
            daily_houses.append({
                'house': house,
                'rashi': rashi_num,
                'rashi_name': ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrischika","Dhanu","Makara","Kumbha","Meena"][rashi_num-1],
                'lord': lord,
                'lord_power': round(lord_power,2),
                'occupants': occupants,
                'occ_avg': round(occ_avg,2),
                'sarva_bindu': sarva_bindu,
                'sarva_corr': sarva_corr,
                'tara_all': tara_all,
                'house_power': round(house_power,2),
                'rating': h_rating
            })
        return {
            'birth_jd': jd_birth,
            'today_jd': jd_today,
            'tara': {'tara_num': tara, 'tara_name': tara_name, 'tara_moon': tara_moon, 'tara_all': tara_all, 'janma_nak': janma_nak+1, 'today_nak': today_nak+1},
            'planets': daily_planets,
            'houses': daily_houses,
            'sarva_bindus': sarva_bindus,
            'combust': combust_corr,
            'yuddha': yuddha_corr,
            'vakri': vakri_corr
        }
    except Exception as e:
        import traceback
        return {'error': str(e), 'traceback': traceback.format_exc()}

