def get_marathi_muhurta(name, period="future"):
    name_low=name.lower()
    for mu in MARATHI_MUHURTAS_DETAILED:
        if name_low in mu["name"].lower() or mu["name"].lower() in name_low:
            return {"query":name,"marathi":mu["marathi"],"rules":f"Tithi {mu['tithi']} Nak {mu['nak']}","purpose":mu["purpose"],"timings":"Brahma 04:24-05:12, Abhijit 11:36-12:24, Godhuli 18:12-19:00","period":period,"panchang":"All Marathi + Surya Siddhanta - Kala Nirnaya,Mahalakshmi,Date,Deshmukh,Drik","surya_siddhanta":SURYA_SIDDHANTA_DETAILS}
    return {"query":name,"available":[m["name"] for m in MARATHI_MUHURTAS_DETAILED]}

def query_marathi_interactive(name):
    return {"message":f"You asked for Marathi muhurta '{name}'. Do you want past 100 years (1926-2025) or future 100 years (2026-2126) or all 200 years?","options":["past","future","all"]}



