def calculate_chandra_bala(janma_rashi, gochara_rashi):
    """Janma Rashi 1-12 (Mesha=1), Gochara Rashi 1-12. Returns Bala status"""
    count = (gochara_rashi - janma_rashi) % 12 + 1
    if count in [1,3,6,7,10,11]:
        return {"count":count, "bala":"Shubh - Strong", "percentage":100}
    elif count in [2,5,9]:
        return {"count":count, "bala":"Madhyam - Medium", "percentage":50}
    else: # 4,8,12
        return {"count":count, "bala":"Ashubh - Weak - Avoid", "percentage":0}

def calculate_guru_bala(janma_rashi, gochara_guru_rashi):
    """Guru in 2,5,7,9,11 shubh"""
    count = (gochara_guru_rashi - janma_rashi) % 12 + 1
    if count in [2,5,7,9,11]:
        return {"count":count, "bala":"Shubh - Guru Bala Ahe", "percentage":100, "vivah_allowed":True}
    else:
        return {"count":count, "bala":"Ashubh - No Guru Bala - Avoid Vivah etc", "percentage":0, "vivah_allowed":False}

def calculate_ravi_bala(janma_rashi, gochara_ravi_rashi):
    count = (gochara_ravi_rashi - janma_rashi) % 12 + 1
    if count in [3,6,10,11]:
        return {"count":count, "bala":"Shubh - Strong", "percentage":100}
    elif count in [1,2,4,5,7,9,12]:
        return {"count":count, "bala":"Madhyam/Ashubh", "percentage":30}
    else: # 8
        return {"count":count, "bala":"Ashubh", "percentage":0}

def calculate_tara_bala(janma_nakshatra, gochara_nakshatra):
    """Janma Nak 1-27, Gochara Nak 1-27. Returns Tara"""
    count = (gochara_nakshatra - janma_nakshatra) % 27 + 1
    tara_num = count % 9
    if tara_num == 0:
        tara_num = 9
    tara_names = {1:"Janma",2:"Sampat",3:"Vipat",4:"Kshema",5:"Pratyari",6:"Sadhaka",7:"Vadha",8:"Mitra",9:"Ati Mitra"}
    tara_name = tara_names[tara_num]
    if tara_num in [2,4,6,8,9]:
        return {"count":count, "tara_num":tara_num, "tara_name":tara_name, "bala":"Shubh", "percentage":100}
    elif tara_num == 1:
        return {"count":count, "tara_num":tara_num, "tara_name":tara_name, "bala":"Madhyam", "percentage":50}
    else: # 3,5,7
        return {"count":count, "tara_num":tara_num, "tara_name":tara_name, "bala":"Ashubh - Avoid", "percentage":0}

def calculate_nakshatra_bala(work, gochara_nakshatra_name):
    """Check if Nakshatra shubh for work"""
    work_nak_map = {
        "Vivah": ["Rohini","Mrigashira","Magha","Uttara Phalguni","Hasta","Swati","Anuradha","Mula","Uttara Ashadha","Uttara Bhadrapada","Revati"],
        "Griha Pravesh": ["Rohini","Mrigashira","Uttara Phalguni","Hasta","Chitra","Anuradha","Uttara Ashadha","Dhanishta","Revati"],
        "Business": ["Ashwini","Rohini","Punarvasu","Pushya","Hasta","Anuradha","Uttara Ashadha","Shravana","Revati"]
    }
    shubh_list = work_nak_map.get(work, work_nak_map["Business"])
    if gochara_nakshatra_name in shubh_list:
        return {"bala":"Shubh","percentage":100}
    else:
        return {"bala":"Ashubh","percentage":0}

def get_personal_muhurta(janma_rashi, janma_nakshatra, work="Vivah", period="future"):
    """
    Main function to get suitable muhurta for a person
    janma_rashi: 1-12 (Mesha=1)
    janma_nakshatra: 1-27 (Ashwini=1)
    work: Vivah, Griha Pravesh, Business, etc
    period: past/future/all
    Returns dates where all 5 Balas shubh
    """
    # This would normally iterate over 73,414 days and calculate all Balas
    # For now, returns logic and sample
    return {
        "janma_rashi": janma_rashi,
        "janma_nakshatra": janma_nakshatra,
        "work": work,
        "period": period,
        "required_balas": ["Chandra Bala 1,3,6,7,10,11","Tara Bala 2,4,6,8,9","Guru Bala 2,5,7,9,11","Ravi Bala 3,6,10,11","Nakshatra Bala specific for work"],
        "message": f"For Janma Rashi {janma_rashi}, Janma Nakshatra {janma_nakshatra}, Work {work} - Need to check 73,414 days from 1926-2126 where all 5 Balas shubh. Use 200 year CSV + calculate Gochara positions. Can provide personalized list.",
        "example": "If Janma Rashi = Karka (4), Guru in Vrishabha (2) = Count 11 = Shubh Guru Bala. Chandra in Kanya (6) from Karka = Count 3 = Shubh Chandra Bala. Tara: Janma Ashwini, day Bharani = Count 2 = Sampat = Shubh Tara Bala."
    }
